/* ============================== UTILITIES ============================== */

const uid = (p = "id") => `${p}_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;

function dateISO(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}
function todayISO() {
  return dateISO(new Date());
}
function parseISO(iso) {
  return new Date(iso + "T00:00:00");
}
function addDays(iso, n) {
  const d = parseISO(iso);
  d.setDate(d.getDate() + n);
  return dateISO(d);
}
function fmtDate(iso) {
  if (!iso) return "\u2014";
  return parseISO(iso).toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
}
function fmtDateShort(iso) {
  if (!iso) return "\u2014";
  return parseISO(iso).toLocaleDateString("en-GB", { day: "2-digit", month: "short" });
}
function fmtMonth(iso) {
  return parseISO(iso).toLocaleDateString("en-US", { month: "short", year: "numeric" });
}
function money(n) {
  const v = Number(n || 0);
  return `${CURRENCY} ${v.toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
}
function monthKey(iso) {
  return iso.slice(0, 7);
}
function startOfMonth(iso) {
  return iso.slice(0, 7) + "-01";
}
function endOfMonth(iso) {
  const d = parseISO(startOfMonth(iso));
  d.setMonth(d.getMonth() + 1);
  d.setDate(0);
  return dateISO(d);
}
function shiftMonths(iso, n) {
  const d = parseISO(startOfMonth(iso));
  d.setMonth(d.getMonth() + n);
  return dateISO(d);
}
function monthsBetween(fromIso, toIso) {
  const out = [];
  let cur = startOfMonth(fromIso);
  const last = startOfMonth(toIso);
  let guard = 0;
  while (cur <= last && guard < 36) {
    out.push(cur);
    cur = shiftMonths(cur, 1);
    guard++;
  }
  return out;
}
function startOfWeek(iso) {
  const d = parseISO(iso);
  const day = (d.getDay() + 6) % 7; // Monday = 0
  d.setDate(d.getDate() - day);
  return dateISO(d);
}
function startOfCalendarMonth(iso) {
  const first = startOfMonth(iso);
  return startOfWeek(first);
}
function monthDays(iso) {
  const first = startOfMonth(iso);
  const last = endOfMonth(iso);
  const gridStart = startOfWeek(first);
  const days = [];
  let cur = gridStart;
  // build 6 rows x 7 cols = 42 days, but trim trailing empty rows beyond month if last row fully outside
  for (let i = 0; i < 42; i++) {
    days.push(cur);
    cur = addDays(cur, 1);
  }
  // trim last row if entirely after month end and after first row containing last day
  while (days.length > 35 && days[days.length - 7] > last) {
    days.splice(days.length - 7, 7);
  }
  return { days, first, last };
}
function weekDays(iso) {
  const start = startOfWeek(iso);
  return Array.from({ length: 7 }, (_, i) => addDays(start, i));
}
function csvEscape(v) {
  const s = String(v ?? "");
  if (/[",\n]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
  return s;
}
function downloadCSV(filename, headers, rows) {
  const lines = [headers.map(csvEscape).join(",")].concat(
    rows.map((r) => r.map(csvEscape).join(","))
  );
  const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
function downloadXLSX(filename, headers, rows) {
  const ws = XLSX.utils.aoa_to_sheet([headers, ...rows]);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Report");
  const wbout = XLSX.write(wb, { bookType: "xlsx", type: "array" });
  const blob = new Blob([wbout], { type: "application/octet-stream" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

/* ============================== SUPABASE DATA LOADING ============================== */
// Loads every operational table in parallel and maps DB (snake_case) rows to the
// same camelCase shape the UI already expects. Location-scoping needs no client-side
// filtering here — RLS already returns only the rows the logged-in admin can see.

async function loadAllData() {
  const [
    locationsRes, paymentPlansRes, batchesRes, coachesRes, coachLocationsRes,
    studentsRes, sessionsRes, sessionCoachesRes, attendanceRes, paymentsRes,
  ] = await Promise.all([
    supabase.from("locations").select("*").order("name"),
    supabase.from("payment_plans").select("*"),
    supabase.from("batches").select("*"),
    supabase.from("coaches").select("*"),
    supabase.from("coach_locations").select("*"),
    supabase.from("students").select("*").order("name"),
    supabase.from("sessions").select("*"),
    supabase.from("session_coaches").select("*"),
    supabase.from("attendance").select("*"),
    supabase.from("payments").select("*"),
  ]);

  const firstError = [
    locationsRes, paymentPlansRes, batchesRes, coachesRes, coachLocationsRes,
    studentsRes, sessionsRes, sessionCoachesRes, attendanceRes, paymentsRes,
  ].find((r) => r.error)?.error;
  if (firstError) throw firstError;

  const locations = (locationsRes.data || []).map((l) => ({
    id: l.id, name: l.name, address: l.address, contact: l.contact,
    admin: l.admin_name || "", adminUserId: l.admin_user_id || "",
  }));
  const paymentPlans = (paymentPlansRes.data || []).map((p) => ({
    id: p.id, locationId: p.location_id, name: p.name, gender: p.gender,
    duration: p.duration, sessionsCount: p.sessions_count ?? "", amount: p.amount,
  }));
  const batches = (batchesRes.data || []).map((b) => ({
    id: b.id, locationId: b.location_id, batchCode: b.batch_code || "", name: b.name,
  }));

  const coachLocMap = {};
  (coachLocationsRes.data || []).forEach((cl) => {
    (coachLocMap[cl.coach_id] ||= []).push(cl.location_id);
  });
  const coaches = (coachesRes.data || []).map((c) => ({
    id: c.id, name: c.name, phone: c.phone || "", email: c.email || "",
    specialty: c.specialty || "", locationIds: coachLocMap[c.id] || [],
  }));

  const students = (studentsRes.data || []).map((s) => ({
    id: s.id, name: s.name, phone: s.phone || "", email: s.email || "", dob: s.dob || "",
    dateOfJoining: s.date_of_joining || "",
    batchId: s.batch_id || "", locationId: s.location_id, jerseyName: s.jersey_name || "",
    jerseyNo: s.jersey_no || "", sessionsPerWeek: s.sessions_per_week ?? 2,
    attendanceDays: s.attendance_days || [],
    paymentPlanId: s.payment_plan_id || "", overrideFee: s.override_fee ?? "",
    status: s.status, remark: s.remark || "",
  }));

  const sessCoachMap = {};
  (sessionCoachesRes.data || []).forEach((sc) => {
    (sessCoachMap[sc.session_id] ||= []).push(sc.coach_id);
  });
  const sessions = (sessionsRes.data || []).map((s) => ({
    id: s.id, locationId: s.location_id, batchId: s.batch_id, date: s.date,
    startTime: (s.start_time || "00:00").slice(0, 5), endTime: (s.end_time || "00:00").slice(0, 5),
    coachIds: sessCoachMap[s.id] || [],
  }));

  const attendance = (attendanceRes.data || []).map((a) => ({
    id: a.id, sessionId: a.session_id, studentId: a.student_id, status: a.status,
  }));
  const payments = (paymentsRes.data || []).map((p) => ({
    id: p.id, studentId: p.student_id, date: p.date, receiptNo: p.receipt_no,
    amount: p.amount, nextPaymentDate: p.next_payment_date || "", comment: p.comment || "",
    paymentType: p.payment_type || "Fee", startDate: p.start_date || "", endDate: p.end_date || "",
    registrationFeeAmount: p.registration_fee_amount ?? "", paymentMode: p.payment_mode || "",
    paymentMonth: p.payment_month || "",
  }));

  return { locations, paymentPlans, batches, coaches, students, sessions, attendance, payments };
}

/* ============================== DOMAIN HELPERS ============================== */

function studentPayments(data, studentId) {
  return data.payments.filter((p) => p.studentId === studentId).sort((a, b) => (a.date < b.date ? 1 : -1));
}
// The payment that determines a student's CURRENT fee due status. Only "Fee" type
// payments count — Extra Jersey / Full Kit payments never carry a next_payment_date and
// must never be picked over (or shadow) an actual fee payment. Among a student's Fee
// payments, the one with the furthest next_payment_date wins — not the one with the
// latest payment `date` — so that two Fee payments recorded on the same date (e.g. a
// catch-up payment and the current month's payment both entered today) are resolved by
// which one actually extends the student furthest, not by arbitrary row order.
function latestPayment(data, studentId) {
  const feePayments = data.payments.filter(
    (p) => p.studentId === studentId && p.paymentType === "Fee" && p.nextPaymentDate
  );
  if (feePayments.length === 0) return null;
  return feePayments.reduce((best, p) => (p.nextPaymentDate > best.nextPaymentDate ? p : best));
}
function studentPlan(data, student) {
  return data.paymentPlans.find((p) => p.id === student.paymentPlanId) || null;
}
function studentExpectedFee(data, student) {
  if (student.overrideFee !== "" && student.overrideFee != null && !isNaN(Number(student.overrideFee))) {
    return Number(student.overrideFee);
  }
  const plan = studentPlan(data, student);
  return plan ? Number(plan.amount) : 0;
}
function studentFeeStatus(data, student) {
  const last = latestPayment(data, student.id);
  if (!last) return "Due";
  if (!last.nextPaymentDate) return "Due";
  if (last.nextPaymentDate > todayISO()) return "Paid";
  return "Due";
}
function feeStatusColor(status) {
  if (status === "Paid") return "var(--teal)";
  if (status === "Overdue") return "var(--red)";
  return "var(--amber)";
}
function batchName(data, batchId) {
  const b = data.batches.find((x) => x.id === batchId);
  return b ? b.name : "\u2014";
}
function locationName(data, locationId) {
  const l = data.locations.find((x) => x.id === locationId);
  return l ? l.name : "\u2014";
}
function coachName(data, coachId) {
  const c = data.coaches.find((x) => x.id === coachId);
  return c ? c.name : "Unassigned";
}
function coachNames(data, coachIds) {
  if (!coachIds || coachIds.length === 0) return "Unassigned";
  return coachIds.map((id) => coachName(data, id)).join(", ");
}
function sessionsCountForStudentInMonth(data, studentId, mKey) {
  const sessIds = new Set(
    data.sessions.filter((s) => monthKey(s.date) === mKey).map((s) => s.id)
  );
  return data.attendance.filter(
    (a) => a.studentId === studentId && a.status === "P" && sessIds.has(a.sessionId)
  ).length;
}
function feePaidForStudentInMonth(data, studentId, mKey) {
  return data.payments
    .filter((p) => p.studentId === studentId && monthKey(p.date) === mKey)
    .reduce((sum, p) => sum + Number(p.amount || 0), 0);
}
// Dashboard "Income" for a given month (mKey, "YYYY-MM"): sum of the Fee
// amount plus the Registration fee amount for every payment whose
// payment_month (which month the payment is FOR, stored "MM/YYYY") is the
// given month — not the payment's actual date.
function totalPaidInMonth(data, students, mKey) {
  const ids = new Set(students.map((s) => s.id));
  const feeMonthKey = `${mKey.slice(5, 7)}/${mKey.slice(0, 4)}`; // "YYYY-MM" -> "MM/YYYY"
  return data.payments
    .filter((p) => ids.has(p.studentId) && p.paymentMonth === feeMonthKey)
    .reduce((sum, p) => sum + Number(p.amount || 0) + Number(p.registrationFeeAmount || 0), 0);
}
// Dashboard-only outstanding figure. Sums totalOverdueAmountFor for exactly the students who
// would show up as a row on Reports > Pending Fees (ReportPendingFee) — overdue (no due date
// yet, or due date has passed) AND isPendingForFees (attended within the last 2 months) — with
// one more condition on top, matching that report's own "No. of sessions(pending payment)"
// column: the student must have at least 1 "Present" attendance record, at their own location,
// dated on or after their due date. EXCEPTION: a student with no fee record at all yet (never
// made a Fee payment, so no due date exists to compare against) is always counted regardless of
// attendance — there's nothing to be "pending since" for them, they just owe their first cycle.
// ADDITIONAL CHECK: that never-paid exception only applies to Active students. An Inactive
// student with no fee record has no due date to have attended a session "after", so they can't
// satisfy the "attended after due date" carve-out and are excluded. Inactive students who DO have
// a due date already have to clear the sessionsAfterDue >= 1 check a few lines below (same as
// everyone else), so nothing else needs to change for them.
// Does not touch the Fee Update page's pending list, which still uses isPendingForFees +
// totalOverdueAmountFor directly and is unaffected by this function.
function computeOutstanding(data, students, asOf) {
  return students.reduce((sum, s) => {
    const last = latestPayment(data, s.id);
    if (!last || !last.nextPaymentDate) {
      if (s.status !== "Active") return sum;
      return sum + totalOverdueAmountFor(data, s, asOf);
    }
    const overdue = last.nextPaymentDate <= asOf;
    if (!overdue || !isPendingForFees(data, s, asOf)) return sum;
    const sessionsAfterDue = data.sessions
      .filter((se) => se.locationId === s.locationId && se.date >= last.nextPaymentDate && se.date <= asOf)
      .filter((se) => data.attendance.some((a) => a.sessionId === se.id && a.studentId === s.id && a.status === "P")).length;
    if (sessionsAfterDue < 1) return sum;
    return sum + totalOverdueAmountFor(data, s, asOf);
  }, 0);
}
function sessionsTakenCount(data, sessions) {
  return sessions.filter((s) => s.date <= todayISO()).length;
}
// Walks billing cycles (of the plan's duration) from the student's last due date up to
// asOf, and only bills a cycle if the student has at least one "Present" attendance
// record within that cycle's date range. This avoids charging for months where the
// student simply didn't attend (e.g. a long break) — see the AARAV KUMAR case: due
// 7 Mar 2026, paid through 6 Mar 2026, then no attendance until August. Only August's
// cycle should be billed, not all 6 elapsed months.
function totalOverdueAmountFor(data, student, asOf) {
  const feePerCycle = studentExpectedFee(data, student);
  const last = latestPayment(data, student.id);
  const today = asOf || todayISO();
  if (!last || !last.nextPaymentDate) return feePerCycle;
  if (last.nextPaymentDate > today) return 0;
  const plan = studentPlan(data, student);
  const duration = plan?.duration || "Monthly";
  const cycleMonths = duration === "Monthly" ? 1 : duration === "Quarterly" ? 3 : duration === "4 Months" ? 4 : null;
  if (cycleMonths == null) return feePerCycle;
  let cycles = 0;
  let cycleStart = startOfMonth(last.nextPaymentDate);
  const horizon = startOfMonth(today);
  let guard = 0;
  while (cycleStart <= horizon && guard < 1200) {
    const cycleEnd = shiftMonths(cycleStart, cycleMonths);
    const attendedThisCycle = data.attendance.some((a) => {
      if (a.studentId !== student.id || a.status !== "P") return false;
      const session = data.sessions.find((se) => se.id === a.sessionId);
      return session && session.date >= cycleStart && session.date < cycleEnd;
    });
    if (attendedThisCycle) cycles += 1;
    cycleStart = cycleEnd;
    guard += 1;
  }
  return cycles * feePerCycle;
}
function sessionsOverdueCountFor(data, student) {
  const last = latestPayment(data, student.id);
  if (!last || !last.nextPaymentDate) return 0;
  return data.sessions
    .filter((se) => se.locationId === student.locationId && se.date > last.nextPaymentDate && se.date <= todayISO())
    .filter((se) => data.attendance.some((a) => a.sessionId === se.id && a.studentId === student.id && a.status === "P"))
    .length;
}
// Until a student has a payment record with a due date, any attended session counts.
// Once a due date exists, only sessions on or after that date count.
function hasAttendedSinceDue(data, student) {
  const cutoff = latestPayment(data, student.id)?.nextPaymentDate;
  return data.attendance.some((a) => {
    if (a.studentId !== student.id || a.status !== "P") return false;
    if (!cutoff) return true;
    const session = data.sessions.find((se) => se.id === a.sessionId);
    return session && session.date >= cutoff;
  });
}
// Whether the student has a "Present" attendance record for any session on or after cutoffIso,
// regardless of how that date relates to the student's next payment date.
function hasAttendedOnOrAfter(data, studentId, cutoffIso) {
  return data.attendance.some((a) => {
    if (a.studentId !== studentId || a.status !== "P") return false;
    const session = data.sessions.find((se) => se.id === a.sessionId);
    return session && session.date >= cutoffIso;
  });
}
// Single source of truth for "does this student belong on a pending/overdue fee list" — has the
// student attended at least one session within the last 2 months (from asOf)? Used by the Pending
// Fees report and the dashboard's outstanding-amount figure, so they stay in sync.
//
// Deliberately recency-only, with no "attended at some point after their due date" branch: that
// check has no upper bound, so a student whose only qualifying attendance is months old (even if it
// was technically after their due date) would stay on the pending list forever off one stale record.
// A student needs to have shown up recently to still be considered pending.
function isPendingForFees(data, student, asOf) {
  const twoMonthsPriorStart = shiftMonths(asOf || todayISO(), -2);
  return hasAttendedOnOrAfter(data, student.id, twoMonthsPriorStart);
}
// Latest session date the student has a "Present" attendance record for, or null if never.
function lastAttendedDate(data, studentId) {
  let latest = null;
  for (const a of data.attendance) {
    if (a.studentId !== studentId || a.status !== "P") continue;
    const session = data.sessions.find((se) => se.id === a.sessionId);
    if (session && (!latest || session.date > latest)) latest = session.date;
  }
  return latest;
}
// True if the student has at least one "Present" record on a session dated after cutoffDate.
function hasAttendedAfter(data, studentId, cutoffDate) {
  return data.attendance.some((a) => {
    if (a.studentId !== studentId || a.status !== "P") return false;
    const session = data.sessions.find((se) => se.id === a.sessionId);
    return session && session.date > cutoffDate;
  });
}
// True if any player has been marked "Present" for this session. Used to block
// deleting a session from Training Schedules once real attendance history exists
// for it — deleting the session would cascade-delete its attendance records.
function sessionHasPresentAttendance(data, sessionId) {
  return data.attendance.some((a) => a.sessionId === sessionId && a.status === "P");
}
// Display-only grouping for read-only widgets (e.g. the dashboard week strip):
// sessions that share date + start/end time + location are folded into one
// group with their batch names comma-joined, e.g. "U6, U8, U10". This does not
// change the underlying data — each session is still its own row — it only
// affects how a list of sessions is rendered. Order is preserved (first
// occurrence order), and sessionIds retains every underlying session id in case
// a caller needs them.
function groupSessionsForDisplay(data, sessions) {
  const groups = [];
  const index = new Map();
  for (const s of sessions) {
    const key = `${s.date}|${s.startTime}|${s.endTime}|${s.locationId}`;
    let g = index.get(key);
    if (!g) {
      g = {
        key, date: s.date, startTime: s.startTime, endTime: s.endTime, locationId: s.locationId,
        batchNames: [], sessionIds: [],
      };
      index.set(key, g);
      groups.push(g);
    }
    g.batchNames.push(batchName(data, s.batchId));
    g.sessionIds.push(s.id);
  }
  return groups;
}
// Turns a failed delete into a message an admin can act on. Postgres error
// code 23503 is a foreign-key violation — with the attendance/payments
// foreign keys set to ON DELETE RESTRICT, this is exactly what fires when a
// delete would otherwise wipe out attendance or payment history, so we call
// that out by name instead of showing the raw Postgres error text.
function friendlyDeleteError(error, label) {
  if (error?.code === "23503") {
    return `Can't delete this ${label} — it still has attendance or payment records linked to it. Remove or reassign those first.`;
  }
  return error?.message || `Couldn't delete this ${label}.`;
}
function studentsAttendedByLocationForMonth(data, mKey) {
  return data.locations.map((l) => {
    const sessIds = new Set(data.sessions.filter((s) => s.locationId === l.id && monthKey(s.date) === mKey).map((s) => s.id));
    const attended = new Set(
      data.attendance.filter((a) => a.status === "P" && sessIds.has(a.sessionId)).map((a) => a.studentId)
    );
    return { name: l.name, attended: attended.size };
  });
}

/* ============================== SHARED UI ============================== */

function JerseyBadge({ no, size = 34 }) {
  return (
    <div
      className="sa-jersey"
      style={{ width: size, height: size, fontSize: size * 0.42 }}
      title={`Jersey #${no}`}
    >
      {no || "--"}
    </div>
  );
}

function Pill({ children, tone = "neutral" }) {
  return <span className={`sa-pill sa-pill-${tone}`}>{children}</span>;
}

function ScoreCard({ label, value, sub, icon: Icon, accent }) {
  return (
    <div className="sa-scorecard">
      <div className="sa-scorecard-top">
        <span className="sa-scorecard-label">{label}</span>
        {Icon && <Icon size={16} strokeWidth={2} style={{ color: accent || "var(--amber)" }} />}
      </div>
      <div className="sa-scorecard-value" style={{ color: accent || "#fff" }}>{value}</div>
      {sub && <div className="sa-scorecard-sub">{sub}</div>}
    </div>
  );
}

function Modal({ title, onClose, children, wide }) {
  return (
    <div className="sa-modal-overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className={`sa-modal ${wide ? "sa-modal-wide" : ""}`}>
        <div className="sa-modal-header">
          <h3>{title}</h3>
          <button className="sa-icon-btn" onClick={onClose}><X size={18} /></button>
        </div>
        <div className="sa-modal-body">{children}</div>
      </div>
    </div>
  );
}

function ConfirmDialog({ message, onConfirm, onCancel }) {
  return (
    <div className="sa-modal-overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) onCancel(); }}>
      <div className="sa-modal sa-modal-confirm">
        <div className="sa-modal-body">
          <div className="sa-confirm-icon"><AlertCircle size={22} /></div>
          <p>{message}</p>
          <div className="sa-form-actions">
            <button className="sa-btn sa-btn-ghost" onClick={onCancel}>Cancel</button>
            <button className="sa-btn sa-btn-danger" onClick={onConfirm}>Delete</button>
          </div>
        </div>
      </div>
    </div>
  );
}

function Field({ label, children, required }) {
  return (
    <label className="sa-field">
      <span>{label}{required && <span className="sa-field-required"> *</span>}</span>
      {children}
    </label>
  );
}

function SearchClearButton({ onClear }) {
  return (
    <button type="button" className="sa-search-clear-btn" onClick={onClear} aria-label="Clear search" tabIndex={-1}>
      <X size={14} />
    </button>
  );
}

function DateInput({ value, onChange, className = "", min, max }) {
  const inputRef = useRef(null);
  return (
    <div className={`sa-date-input ${className}`} onClick={() => inputRef.current?.showPicker?.()}>
      <input ref={inputRef} type="date" value={value} onChange={onChange} min={min} max={max} />
      <span className="sa-date-display">{value ? fmtDate(value) : ""}</span>
    </div>
  );
}

function EmptyState({ icon: Icon, title, message }) {
  return (
    <div className="sa-empty">
      <Icon size={28} strokeWidth={1.5} />
      <h4>{title}</h4>
      <p>{message}</p>
    </div>
  );
}

