/* ============================== DASHBOARD ============================== */

function DashboardPage({ data, dashLocationId, setDashLocationId }) {
  const scopedStudents = useMemo(
    () => data.students.filter((s) => dashLocationId === "ALL" || s.locationId === dashLocationId),
    [data.students, dashLocationId]
  );
  const scopedSessions = useMemo(
    () => data.sessions.filter((s) => dashLocationId === "ALL" || s.locationId === dashLocationId),
    [data.sessions, dashLocationId]
  );
  const activeCount = scopedStudents.filter((s) => s.status === "Active").length;
  const inactiveCount = scopedStudents.filter((s) => s.status !== "Active").length;
  const scopedCoaches = useMemo(
    () => data.coaches.filter((c) => dashLocationId === "ALL" || c.locationIds.includes(dashLocationId)),
    [data.coaches, dashLocationId]
  );
  const currentMonthKey = monthKey(todayISO());
  const paid = totalPaidInMonth(data, scopedStudents, currentMonthKey);
  const outstanding = computeOutstanding(data, scopedStudents, todayISO());
  const revenue = paid + outstanding;

  // Shared month picker for both dashboard charts below (Revenue & Attendance by Location, and
  // Revenue Split & Enrollment by Location) — one selection drives them both. Defaults to the
  // current month, with a range covering the past 12 months (floored at DASHBOARD_TREND_MIN_MONTH
  // so it never reaches earlier than the academy's data start).
  const [trendMonthKey, setTrendMonthKey] = useState(currentMonthKey);
  const trendMinMonthKey = monthKey(shiftMonths(todayISO(), -11)) > DASHBOARD_TREND_MIN_MONTH
    ? monthKey(shiftMonths(todayISO(), -11))
    : DASHBOARD_TREND_MIN_MONTH;

  // Outstanding is always "as of today" (it's not a historical monthly figure the way Paid is),
  // so it's only folded into the chart when the picker is on the current month — for any other
  // month the bar is Paid only, same as before.
  const isTrendCurrentMonth = trendMonthKey === currentMonthKey;
  const attendedByLocationRaw = studentsAttendedByLocationForMonth(data, trendMonthKey);
  const combinedByLocation = data.locations.map((l, i) => {
    const locationStudents = data.students.filter((s) => s.locationId === l.id);
    const paidAmt = totalPaidInMonth(data, locationStudents, trendMonthKey);
    const outstandingAmt = isTrendCurrentMonth ? computeOutstanding(data, locationStudents, todayISO()) : 0;
    return {
      name: l.name,
      paid: paidAmt,
      outstanding: outstandingAmt,
      revenue: paidAmt + outstandingAmt,
      attended: attendedByLocationRaw[i]?.attended || 0,
    };
  });

  // Revenue Split & Enrollment by Location: shares the month picker above (trendMonthKey) rather
  // than having its own, so both charts always show the same month. Hidden by default — see
  // showEnrollmentChart below — and expanded on request. Revenue is broken into what makes it up
  // (registration fee, session fees, jersey/kit sales); enrollment splits each location's roster
  // into students who joined in the selected month ("new") vs students who joined in an earlier
  // month ("existing").
  const [showEnrollmentChart, setShowEnrollmentChart] = useState(false);
  const enrollFeeMonthKey = `${trendMonthKey.slice(5, 7)}/${trendMonthKey.slice(0, 4)}`; // "YYYY-MM" -> "MM/YYYY"
  const revenueEnrollByLocation = data.locations.map((l) => {
    const locationStudents = data.students.filter((s) => s.locationId === l.id);
    const ids = new Set(locationStudents.map((s) => s.id));
    const monthPayments = data.payments.filter((p) => ids.has(p.studentId) && p.paymentMonth === enrollFeeMonthKey);
    const registrationFee = monthPayments.reduce((sum, p) => sum + Number(p.registrationFeeAmount || 0), 0);
    const sessionFees = monthPayments.filter((p) => p.paymentType === "Fee").reduce((sum, p) => sum + Number(p.amount || 0), 0);
    const kitFees = monthPayments.filter((p) => p.paymentType === "Extra Jersey" || p.paymentType === "Full Kit").reduce((sum, p) => sum + Number(p.amount || 0), 0);

    // A student with no recorded Date of Joining can't be classified as "new this month" — there's
    // nothing to compare — so they default into "existing" rather than being silently dropped from
    // the split. A student who joined AFTER the selected month isn't part of that month's roster yet
    // and is excluded from both buckets.
    let newJoinees = 0;
    let existingStudents = 0;
    locationStudents.forEach((s) => {
      if (!s.dateOfJoining) { existingStudents += 1; return; }
      const joinMonth = monthKey(s.dateOfJoining);
      if (joinMonth === trendMonthKey) newJoinees += 1;
      else if (joinMonth < trendMonthKey) existingStudents += 1;
    });

    return {
      name: l.name,
      registrationFee, sessionFees, kitFees,
      revenueTotal: registrationFee + sessionFees + kitFees,
      existingStudents, newJoinees,
      studentTotal: existingStudents + newJoinees,
    };
  });

  const today = todayISO();
  const weekDates = weekDays(today);
  const weekSessions = weekDates.map((d) => {
    const daySessions = scopedSessions.filter((s) => s.date === d).sort((a, b) => (a.startTime || "").localeCompare(b.startTime || ""));
    // Sessions sharing date + start/end time + location (e.g. U6/U8/U10 all at
    // 16:00-17:00 at the same location) are shown as one chip here — this is a
    // read-only glance widget, so grouping is purely cosmetic.
    return { date: d, items: groupSessionsForDisplay(data, daySessions) };
  });

  return (
    <div className="sa-page">
      <div className="sa-scoreboard">
        <ScoreCard
          label="Players"
          value={scopedStudents.length}
          sub={`${activeCount} active \u00b7 ${inactiveCount} inactive`}
          icon={UserRound}
          accent="var(--amber)"
        />
        <ScoreCard
          label="Coaches"
          value={scopedCoaches.length}
          sub={`${sessionsTakenCount(data, scopedSessions)} sessions completed`}
          icon={Users}
          accent="#7DD3FC"
        />
        <ScoreCard
          label="Current Month Revenue"
          value={money(revenue)}
          sub={`${money(paid)} paid \u00b7 ${money(outstanding)} outstanding`}
          icon={Wallet}
          accent="var(--teal)"
        />
      </div>

      <div className="sa-dash-grid">
        <div className="sa-card">
          <div className="sa-card-header">
            <h3>Revenue &amp; Attendance by Location</h3>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <TrendingUp size={16} style={{ color: "var(--muted)" }} />
              <input
                type="month"
                className="sa-inline-select"
                title="Also sets the month for Revenue Split & Enrollment by Location below"
                value={trendMonthKey}
                min={trendMinMonthKey}
                max={currentMonthKey}
                onChange={(e) => e.target.value && setTrendMonthKey(e.target.value)}
              />
            </div>
          </div>
          <div style={{ width: "100%", height: 280 }}>
            <ResponsiveContainer>
              <BarChart data={combinedByLocation} margin={{ top: 28, right: 8, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#EAEAE5" vertical={false} />
                <XAxis dataKey="name" tick={{ fontSize: 12, fill: "#6B7280" }} axisLine={false} tickLine={false} />
                {/* domain headroom so the on-bar total label (rendered above the tallest bar) has
                    room to draw instead of being clipped by the chart's top edge */}
                <YAxis yAxisId="left" domain={[0, (dataMax) => Math.ceil(dataMax * 1.15)]} tick={{ fontSize: 12, fill: "#6B7280" }} axisLine={false} tickLine={false} />
                <YAxis yAxisId="right" orientation="right" allowDecimals={false} tick={{ fontSize: 12, fill: "#6B7280" }} axisLine={false} tickLine={false} />
                <Tooltip
                  formatter={(v, name) => {
                    if (name === "paid") return [money(v), "Paid"];
                    if (name === "outstanding") return [money(v), "Outstanding (as of today)"];
                    return [`${v} players`, "Attended"];
                  }}
                  contentStyle={{ borderRadius: 8, border: "1px solid #E5E7EB", fontSize: 13, fontFamily: "Inter" }}
                />
                <Legend
                  wrapperStyle={{ fontSize: 12 }}
                  formatter={(value) => (value === "paid" ? "Paid" : value === "outstanding" ? "Outstanding" : "Players Attended")}
                />
                <Bar yAxisId="left" dataKey="paid" stackId="revenue" name="paid" fill="#14B8A6" radius={isTrendCurrentMonth ? [0, 0, 6, 6] : [6, 6, 0, 0]}>
                  {!isTrendCurrentMonth && (
                    <LabelList dataKey="paid" position="top" formatter={(v) => money(v)} style={{ fontSize: 11, fontFamily: "Inter", fontWeight: 600, fill: "#101826" }} />
                  )}
                </Bar>
                {isTrendCurrentMonth && (
                  <Bar yAxisId="left" dataKey="outstanding" stackId="revenue" name="outstanding" fill="#EF4444" radius={[6, 6, 0, 0]}>
                    <LabelList dataKey="revenue" position="top" formatter={(v) => money(v)} style={{ fontSize: 11, fontFamily: "Inter", fontWeight: 600, fill: "#101826" }} />
                  </Bar>
                )}
                <Bar yAxisId="right" dataKey="attended" name="attended" fill="#FFB020" radius={[6, 6, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="sa-card">
          <div className="sa-card-header">
            <h3>Revenue Split &amp; Enrollment by Location</h3>
            <button className="sa-icon-btn" onClick={() => setShowEnrollmentChart(!showEnrollmentChart)}>
              {showEnrollmentChart ? "Hide" : "Show"}
            </button>
          </div>
          {showEnrollmentChart && (
          <div style={{ width: "100%", height: 280 }}>
            <ResponsiveContainer>
              <BarChart data={revenueEnrollByLocation} margin={{ top: 28, right: 8, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#EAEAE5" vertical={false} />
                <XAxis dataKey="name" tick={{ fontSize: 12, fill: "#6B7280" }} axisLine={false} tickLine={false} />
                {/* domain headroom on both axes so the on-bar total labels (rendered above the
                    tallest bar on each side) have room to draw instead of being clipped */}
                <YAxis yAxisId="left" domain={[0, (dataMax) => Math.ceil(dataMax * 1.15)]} tick={{ fontSize: 12, fill: "#6B7280" }} axisLine={false} tickLine={false} />
                <YAxis yAxisId="right" orientation="right" allowDecimals={false} domain={[0, (dataMax) => Math.ceil(dataMax * 1.15)]} tick={{ fontSize: 12, fill: "#6B7280" }} axisLine={false} tickLine={false} />
                <Tooltip
                  formatter={(v, name) => {
                    if (name === "registrationFee") return [money(v), "Registration Fee"];
                    if (name === "sessionFees") return [money(v), "Session Fees"];
                    if (name === "kitFees") return [money(v), "Jersey / Full Kit"];
                    if (name === "existingStudents") return [`${v} students`, "Existing Students"];
                    return [`${v} students`, "New Joinees"];
                  }}
                  // Existing Students listed above New Joinees in the hover box, independent of
                  // stacking order (which stays bottom=Existing / top=New on the bar itself).
                  itemSorter={(item) => ({
                    registrationFee: 0, sessionFees: 1, kitFees: 2, existingStudents: 3, newJoinees: 4,
                  }[item.dataKey] ?? 99)}
                  contentStyle={{ borderRadius: 8, border: "1px solid #E5E7EB", fontSize: 13, fontFamily: "Inter" }}
                />
                <Legend
                  wrapperStyle={{ fontSize: 12 }}
                  formatter={(value) => ({
                    registrationFee: "Registration Fee",
                    sessionFees: "Session Fees",
                    kitFees: "Jersey / Full Kit",
                    existingStudents: "Existing Students",
                    newJoinees: "New Joinees",
                  }[value] || value)}
                />
                {/* Registration Fee shares its color with New Joinees (blue) and Session Fees
                    shares its color with Existing Students (green) — a registration fee is what a
                    brand-new joiner pays, and session fees are the recurring fee existing students
                    keep paying, so the two bars read as one story in matching colors. */}
                <Bar yAxisId="left" dataKey="registrationFee" stackId="revenueSplit" name="registrationFee" fill="#2a78d6" radius={[0, 0, 6, 6]} />
                <Bar yAxisId="left" dataKey="sessionFees" stackId="revenueSplit" name="sessionFees" fill="#1BAF7A" radius={[0, 0, 0, 0]} />
                <Bar yAxisId="left" dataKey="kitFees" stackId="revenueSplit" name="kitFees" fill="#EB6834" radius={[6, 6, 0, 0]}>
                  <LabelList dataKey="revenueTotal" position="top" formatter={(v) => money(v)} style={{ fontSize: 11, fontFamily: "Inter", fontWeight: 600, fill: "#101826" }} />
                </Bar>
                <Bar yAxisId="right" dataKey="existingStudents" stackId="enrollment" name="existingStudents" fill="#1BAF7A" radius={[0, 0, 6, 6]} />
                <Bar yAxisId="right" dataKey="newJoinees" stackId="enrollment" name="newJoinees" fill="#2a78d6" radius={[6, 6, 0, 0]}>
                  <LabelList dataKey="studentTotal" position="top" formatter={(v) => `${v}`} style={{ fontSize: 11, fontFamily: "Inter", fontWeight: 600, fill: "#101826" }} />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          )}
        </div>

        <div className="sa-card">
          <div className="sa-card-header">
            <h3>This Week's Schedule</h3>
            <select
              className="sa-inline-select"
              value={dashLocationId}
              onChange={(e) => setDashLocationId(e.target.value)}
            >
              <option value="ALL">All Locations</option>
              {data.locations.map((l) => (
                <option key={l.id} value={l.id}>{l.name}</option>
              ))}
            </select>
          </div>
          <div className="sa-week-strip">
            {weekSessions.map(({ date, items }) => (
              <div key={date} className={`sa-week-col ${date === today ? "sa-week-col-today" : ""}`}>
                <div className="sa-week-col-head">
                  <span>{parseISO(date).toLocaleDateString("en-US", { weekday: "short" })}</span>
                  <span className="sa-week-col-date">{parseISO(date).getDate()}</span>
                </div>
                {items.length === 0 && <div className="sa-week-empty" />}
                {items.map((g) => (
                  <div key={g.key} className="sa-week-chip">
                    <span className="sa-week-chip-time">{g.startTime}-{g.endTime}</span>
                    <span className="sa-week-chip-batch">{g.batchNames.join(", ")}</span>
                    <span className="sa-week-chip-loc">{locationName(data, g.locationId)}</span>
                  </div>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ============================== LOCATIONS ============================== */

function LocationsPage({ data, refetchData }) {
  const [modal, setModal] = useState(null); // { mode: 'add'|'edit', location }
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [saveError, setSaveError] = useState(null);
  const [form, setForm] = useState({ name: "", address: "", contact: "", admin: "", adminUserId: "" });
  const [saving, setSaving] = useState(false);
  const savingRef = useRef(false); // synchronous guard — blocks a second click before the "saving" state has re-rendered

  const openAdd = () => { setForm({ name: "", address: "", contact: "", admin: "", adminUserId: "" }); setModal({ mode: "add" }); };
  const openEdit = (loc) => { setForm(loc); setModal({ mode: "edit", id: loc.id }); };

  const save = async () => {
    if (!form.name.trim() || savingRef.current) return;
    savingRef.current = true;
    setSaving(true);
    try {
      const payload = {
        name: form.name, address: form.address, contact: form.contact,
        admin_name: form.admin, admin_user_id: form.adminUserId || null,
      };
      const { error } = modal.mode === "add"
        ? await supabase.from("locations").insert(payload)
        : await supabase.from("locations").update(payload).eq("id", modal.id);
      if (error) { setSaveError(error.message); return; }
      setSaveError(null);
      await refetchData();
      setModal(null);
    } finally {
      savingRef.current = false;
      setSaving(false);
    }
  };

  const remove = async (id) => {
    const { error } = await supabase.from("locations").delete().eq("id", id);
    if (error) { setSaveError(friendlyDeleteError(error, "location")); setConfirmDelete(null); return; }
    setSaveError(null);
    await refetchData();
    setConfirmDelete(null);
  };

  return (
    <div className="sa-page">
      {saveError && <div className="sa-login-error"><AlertCircle size={14} /> {saveError}</div>}
      <div className="sa-page-actions">
        <div />
        <button className="sa-btn sa-btn-primary" onClick={openAdd}><Plus size={16} /> Add Location</button>
      </div>

      {data.locations.length === 0 ? (
        <EmptyState icon={MapPin} title="No locations yet" message="Add your first academy location to get started." />
      ) : (
        <div className="sa-card-grid">
          {data.locations.map((loc) => {
            const studentCount = data.students.filter((s) => s.locationId === loc.id).length;
            const coachCount = data.coaches.filter((c) => c.locationIds.includes(loc.id)).length;
            return (
              <div key={loc.id} className="sa-loc-card">
                <div className="sa-loc-card-top">
                  <div className="sa-loc-icon"><MapPin size={18} /></div>
                  <div className="sa-loc-card-actions">
                    <button className="sa-icon-btn" onClick={() => openEdit(loc)}><Pencil size={14} /></button>
                    <button className="sa-icon-btn" onClick={() => setConfirmDelete(loc.id)}><Trash2 size={14} /></button>
                  </div>
                </div>
                <h3>{loc.name}</h3>
                <p className="sa-loc-address">{loc.address}</p>
                <div className="sa-loc-meta">
                  <span><Phone size={12} /> {loc.contact}</span>
                  <span>Admin: {loc.admin || "\u2014"}</span>
                </div>
                <div className="sa-loc-stats">
                  <span>{studentCount} players</span>
                  <span>{coachCount} coaches</span>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {modal && (
        <Modal title={modal.mode === "add" ? "Add Location" : "Edit Location"} onClose={() => setModal(null)}>
          <div className="sa-form">
            <Field label="Location Name">
              <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Downtown Arena" />
            </Field>
            <Field label="Address">
              <input value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} placeholder="Street, city" />
            </Field>
            <Field label="Contact Number">
              <input value={form.contact} onChange={(e) => setForm({ ...form, contact: e.target.value })} placeholder="+971 ..." />
            </Field>
            <Field label="Admin In Charge">
              <input value={form.admin} onChange={(e) => setForm({ ...form, admin: e.target.value })} placeholder="Name" />
            </Field>
            <Field label="Admin User ID">
              <input value={form.adminUserId} onChange={(e) => setForm({ ...form, adminUserId: e.target.value })} placeholder="e.g. admin.downtown" />
            </Field>
            <div className="sa-form-actions">
              <button className="sa-btn sa-btn-ghost" disabled={saving} onClick={() => setModal(null)}>Cancel</button>
              <button className="sa-btn sa-btn-primary" disabled={saving} onClick={save}>{saving ? "Saving…" : "Save Location"}</button>
            </div>
          </div>
        </Modal>
      )}

      {confirmDelete && (
        <ConfirmDialog
          message="Delete this location? This also deletes its batches, schedules, payment plans, and any players with no attendance or payment history. If any player at this location has attendance or payment records, the location can't be deleted until those are resolved."
          onCancel={() => setConfirmDelete(null)}
          onConfirm={() => remove(confirmDelete)}
        />
      )}
    </div>
  );
}

