function PaymentPlansPage({ data, refetchData, locationId }) {
  const [modal, setModal] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [saveError, setSaveError] = useState(null);
  const blank = { name: "", gender: "Any", duration: "Monthly", sessionsCount: "", amount: "" };
  const [form, setForm] = useState(blank);
  const [saving, setSaving] = useState(false);
  const savingRef = useRef(false);

  const plans = data.paymentPlans.filter((p) => p.locationId === locationId);

  const openAdd = () => { setForm(blank); setModal({ mode: "add" }); };
  const openEdit = (p) => { setForm(p); setModal({ mode: "edit", id: p.id }); };

  const save = async () => {
    if (!form.name.trim() || form.amount === "" || savingRef.current) return;
    savingRef.current = true;
    setSaving(true);
    try {
      const payload = {
        location_id: locationId, name: form.name, gender: form.gender, duration: form.duration,
        sessions_count: form.sessionsCount === "" ? null : Number(form.sessionsCount),
        amount: Number(form.amount),
      };
      const { error } = modal.mode === "add"
        ? await supabase.from("payment_plans").insert(payload)
        : await supabase.from("payment_plans").update(payload).eq("id", modal.id);
      if (error) { setSaveError(error.message); return; }
      setSaveError(null);
      await refetchData();
      setModal(null);
    } finally {
      savingRef.current = false;
      setSaving(false);
    }
  };

  const remove = async (id) => {
    const { error } = await supabase.from("payment_plans").delete().eq("id", id);
    if (error) { setSaveError(friendlyDeleteError(error, "payment plan")); setConfirmDelete(null); return; }
    setSaveError(null);
    await refetchData();
    setConfirmDelete(null);
  };

  if (!locationId) return <EmptyState icon={Wallet} title="No location selected" message="Add a location first." />;

  return (
    <div className="sa-page">
      {saveError && <div className="sa-login-error"><AlertCircle size={14} /> {saveError}</div>}
      <div className="sa-page-actions">
        <div />
        <button className="sa-btn sa-btn-primary" onClick={openAdd}><Plus size={16} /> Add Payment Plan</button>
      </div>

      {plans.length === 0 ? (
        <EmptyState icon={Wallet} title="No payment plans" message="Create a payment plan for this location." />
      ) : (
        <div className="sa-table-wrap">
          <table className="sa-table sa-table-compact">
            <thead>
              <tr>
                <th>Plan Name</th><th>Gender</th><th>Duration</th><th>Sessions</th><th>Amount</th><th></th>
              </tr>
            </thead>
            <tbody>
              {plans.map((p) => (
                <tr key={p.id}>
                  <td className="sa-td-strong">{p.name}</td>
                  <td>{p.gender}</td>
                  <td>{p.duration}</td>
                  <td>{p.duration === "Fixed Sessions" ? p.sessionsCount : "\u2014"}</td>
                  <td className="sa-mono">{money(p.amount)}</td>
                  <td className="sa-td-actions">
                    <button className="sa-icon-btn" onClick={() => openEdit(p)}><Pencil size={14} /></button>
                    <button className="sa-icon-btn" onClick={() => setConfirmDelete(p.id)}><Trash2 size={14} /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {modal && (
        <Modal title={modal.mode === "add" ? "Add Payment Plan" : "Edit Payment Plan"} onClose={() => setModal(null)}>
          <div className="sa-form">
            <Field label="Plan Name">
              <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Monthly - Any" />
            </Field>
            <div className="sa-form-row">
              <Field label="Gender">
                <select value={form.gender} onChange={(e) => setForm({ ...form, gender: e.target.value })}>
                  {GENDERS.map((g) => <option key={g} value={g}>{g}</option>)}
                </select>
              </Field>
              <Field label="Duration">
                <select value={form.duration} onChange={(e) => setForm({ ...form, duration: e.target.value })}>
                  {DURATIONS.map((g) => <option key={g} value={g}>{g}</option>)}
                </select>
              </Field>
            </div>
            {form.duration === "Fixed Sessions" && (
              <Field label="Number of Sessions">
                <input type="number" min="1" value={form.sessionsCount} onChange={(e) => setForm({ ...form, sessionsCount: e.target.value })} />
              </Field>
            )}
            <Field label={`Amount (${CURRENCY})`}>
              <input type="number" min="0" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} />
            </Field>
            <div className="sa-form-actions">
              <button className="sa-btn sa-btn-ghost" disabled={saving} onClick={() => setModal(null)}>Cancel</button>
              <button className="sa-btn sa-btn-primary" disabled={saving} onClick={save}>{saving ? "Saving…" : "Save Plan"}</button>
            </div>
          </div>
        </Modal>
      )}

      {confirmDelete && (
        <ConfirmDialog message="Delete this payment plan?" onCancel={() => setConfirmDelete(null)} onConfirm={() => remove(confirmDelete)} />
      )}
    </div>
  );
}

