// Lets an admin pick a cutoff date, review every currently-Active player with no
// "Present" attendance after that date, deselect any they want to keep, then
// bulk-apply status = "Inactive" to the rest. Nothing is written until confirmed.
function InactivityReviewModal({ data, locationId, onClose, refetchData }) {
  const defaultCutoff = dateISO(new Date(Date.now() - 30 * 24 * 60 * 60 * 1000));
  const [cutoff, setCutoff] = useState(defaultCutoff);
  const [skipRecentJoiners, setSkipRecentJoiners] = useState(true);
  const [selected, setSelected] = useState(() => new Set());
  const [applying, setApplying] = useState(false);
  const applyingRef = useRef(false);
  const [saveError, setSaveError] = useState(null);

  const candidates = useMemo(() => {
    return data.students
      .filter((s) => s.status === "Active")
      .filter((s) => locationId === "ALL" || s.locationId === locationId)
      .filter((s) => !skipRecentJoiners || !s.dateOfJoining || s.dateOfJoining <= cutoff)
      .filter((s) => !hasAttendedAfter(data, s.id, cutoff))
      .map((s) => ({ student: s, last: lastAttendedDate(data, s.id) }));
  }, [data, locationId, cutoff, skipRecentJoiners]);

  // Default every new candidate list to "all selected" until the admin manually
  // unchecks something; re-selecting all resets after the filters change.
  useEffect(() => {
    setSelected(new Set(candidates.map((c) => c.student.id)));
  }, [candidates]);

  const toggle = (id) => {
    const next = new Set(selected);
    if (next.has(id)) next.delete(id); else next.add(id);
    setSelected(next);
  };
  const toggleAll = () => {
    if (selected.size === candidates.length) setSelected(new Set());
    else setSelected(new Set(candidates.map((c) => c.student.id)));
  };

  const apply = async () => {
    if (selected.size === 0 || applyingRef.current) return;
    applyingRef.current = true;
    setApplying(true);
    try {
      const { error } = await supabase.from("students").update({ status: "Inactive" }).in("id", [...selected]);
      if (error) { setSaveError(error.message); return; }
      setSaveError(null);
      await refetchData();
      onClose();
    } finally {
      applyingRef.current = false;
      setApplying(false);
    }
  };

  return (
    <Modal title="Review & Mark Inactive" onClose={onClose} wide>
      {saveError && <div className="sa-login-error"><AlertCircle size={14} /> {saveError}</div>}
      <p className="sa-muted-text">
        Shows currently Active players with no attendance marked "Present" after the date below. Nothing changes until you click Apply.
      </p>
      <div className="sa-form-row">
        <Field label="No Present attendance after">
          <DateInput value={cutoff} onChange={(e) => setCutoff(e.target.value)} max={todayISO()} />
        </Field>
        <Field label="Recent joiners">
          <label style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 8 }}>
            <input type="checkbox" checked={skipRecentJoiners} onChange={(e) => setSkipRecentJoiners(e.target.checked)} />
            Skip players who joined after the cutoff
          </label>
        </Field>
      </div>

      {candidates.length === 0 ? (
        <EmptyState icon={UserX} title="No candidates" message="No Active player matches this cutoff." />
      ) : (
        <div className="sa-table-wrap">
          <table className="sa-table sa-table-compact">
            <thead>
              <tr>
                <th><input type="checkbox" checked={selected.size === candidates.length} onChange={toggleAll} /></th>
                <th>Name</th><th>Batch</th><th>Location</th><th>Joined</th><th>Last Attended</th>
              </tr>
            </thead>
            <tbody>
              {candidates.map(({ student: s, last }) => (
                <tr key={s.id}>
                  <td><input type="checkbox" checked={selected.has(s.id)} onChange={() => toggle(s.id)} /></td>
                  <td className="sa-td-strong">{s.name}</td>
                  <td>{batchName(data, s.batchId)}</td>
                  <td>{locationName(data, s.locationId)}</td>
                  <td>{fmtDate(s.dateOfJoining)}</td>
                  <td>{last ? fmtDate(last) : "Never"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <div className="sa-form-actions">
        <button className="sa-btn sa-btn-ghost" onClick={onClose}>Cancel</button>
        <button className="sa-btn sa-btn-primary" disabled={selected.size === 0 || applying} onClick={apply}>
          {applying ? "Applying…" : `Mark ${selected.size} Inactive`}
        </button>
      </div>
    </Modal>
  );
}

function StudentsPage({ data, refetchData, locationId }) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");
  const [modal, setModal] = useState(null);
  const [detailId, setDetailId] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [remarkStudentId, setRemarkStudentId] = useState(null);
  const [saveError, setSaveError] = useState(null);
  const [inactivityReviewOpen, setInactivityReviewOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const savingRef = useRef(false);

  const blank = {
    name: "", phone: "", email: "", dob: "", dateOfJoining: "", batchId: "",
    locationId: locationId === "ALL" ? (data.locations[0]?.id || "") : locationId,
    jerseyName: "", jerseyNo: "", sessionsPerWeek: 0, attendanceDays: [], paymentPlanId: "", overrideFee: "", status: "Active", remark: "",
  };

  const filtered = data.students.filter((s) => {
    if (locationId !== "ALL" && s.locationId !== locationId) return false;
    if (statusFilter !== "All" && s.status !== statusFilter) return false;
    const q = search.trim().toLowerCase();
    if (!q) return true;
    return (
      s.name.toLowerCase().includes(q) ||
      (s.jerseyName || "").toLowerCase().includes(q) ||
      String(s.jerseyNo).toLowerCase().includes(q)
    );
  });

  const openAdd = () => setModal({ mode: "add" });
  const openEdit = (s) => setModal({ mode: "edit", id: s.id, initial: s });

  const save = async (form) => {
    if (savingRef.current) return;
    savingRef.current = true;
    setSaving(true);
    try {
      const payload = {
        name: form.name, phone: form.phone, email: form.email, dob: form.dob || null,
        date_of_joining: form.dateOfJoining || null,
        batch_id: form.batchId || null, location_id: form.locationId,
        jersey_name: form.jerseyName, jersey_no: form.jerseyNo,
        sessions_per_week: form.attendanceDays.length, attendance_days: form.attendanceDays,
        payment_plan_id: form.paymentPlanId || null,
        override_fee: form.overrideFee === "" ? null : Number(form.overrideFee),
        status: form.status, remark: form.remark || null,
      };
      const { error } = modal.mode === "add"
        ? await supabase.from("students").insert(payload)
        : await supabase.from("students").update(payload).eq("id", modal.id);
      if (error) { setSaveError(error.message); return; }
      setSaveError(null);
      await refetchData();
      setModal(null);
    } finally {
      savingRef.current = false;
      setSaving(false);
    }
  };

  const remove = async (id) => {
    const { error } = await supabase.from("students").delete().eq("id", id);
    if (error) { setSaveError(friendlyDeleteError(error, "player")); setConfirmDelete(null); return; }
    setSaveError(null);
    await refetchData();
    setConfirmDelete(null);
  };

  const detailStudent = data.students.find((s) => s.id === detailId);

  const locationStudents = data.students.filter((s) => locationId === "ALL" || s.locationId === locationId);
  const activeTotal = locationStudents.filter((s) => s.status === "Active").length;
  const inactiveTotal = locationStudents.filter((s) => s.status !== "Active").length;

  return (
    <div className="sa-page">
      <div className="sa-scoreboard">
        <ScoreCard label="Active Players" value={activeTotal} icon={UserRound} accent="var(--teal)" />
        <ScoreCard label="Inactive Players" value={inactiveTotal} icon={UserRound} accent="var(--red)" />
      </div>

      <div className="sa-page-actions">
        <div className="sa-search-row">
          <div className="sa-search-box" style={{ minWidth: "min(420px, 100%)" }}>
            <Search size={15} />
            <input placeholder="Search by name, jersey name, or jersey no." value={search} onChange={(e) => setSearch(e.target.value)} autoComplete="off" autoCorrect="off" autoCapitalize="off" spellCheck={false} />
            {search && <SearchClearButton onClear={() => setSearch("")} />}
          </div>
          <select className="sa-inline-select" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option>All</option><option>Active</option><option>Inactive</option>
          </select>
        </div>
        <button className="sa-btn sa-btn-ghost" onClick={() => setInactivityReviewOpen(true)}><UserX size={16} /> Review Inactivity</button>
        <button className="sa-btn sa-btn-primary" onClick={openAdd}><Plus size={16} /> Add Player</button>
      </div>

      {filtered.length === 0 ? (
        <EmptyState icon={UserRound} title="No players found" message="Try adjusting filters or add a new player." />
      ) : (
        <div className="sa-table-wrap">
          <table className="sa-table sa-table-compact">
            <thead>
              <tr>
                <th>Name</th><th>Jersey Name</th><th>Jersey No.</th><th>Batch</th><th>Phone No.</th><th>Fee Status</th><th>Location</th><th></th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((s) => {
                const status = studentFeeStatus(data, s);
                return (
                  <tr key={s.id} className="sa-row-clickable" onClick={() => setDetailId(s.id)}>
                    <td className="sa-td-strong">{s.name}{s.status === "Inactive" && <Pill tone="red"> Inactive</Pill>}</td>
                    <td>{s.jerseyName || "\u2014"}</td>
                    <td>#{s.jerseyNo}</td>
                    <td>{batchName(data, s.batchId)}</td>
                    <td>{s.phone}</td>
                    <td><Pill tone={status === "Paid" ? "teal" : status === "Overdue" ? "red" : "amber"}>{status}</Pill></td>
                    <td>{locationName(data, s.locationId)}</td>
                    <td className="sa-td-actions" onClick={(e) => e.stopPropagation()}>
                      {s.remark && s.remark.trim() ? (
                        <button className="sa-icon-btn" title="View remark" onClick={() => setRemarkStudentId(s.id)}><MessageSquare size={14} /></button>
                      ) : (
                        <span className="sa-icon-btn-placeholder" />
                      )}
                      <button className="sa-icon-btn" onClick={() => openEdit(s)}><Pencil size={14} /></button>
                      <button className="sa-icon-btn" onClick={() => setConfirmDelete(s.id)}><Trash2 size={14} /></button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {modal && (
        <Modal title={modal.mode === "add" ? "Add Player" : "Edit Player"} onClose={() => setModal(null)} wide>
          {saveError && <div className="sa-login-error"><AlertCircle size={14} /> {saveError}</div>}
          <StudentForm
            data={data}
            locationId={locationId}
            initial={modal.mode === "add" ? blank : modal.initial}
            submitting={saving}
            onCancel={() => setModal(null)}
            onSave={save}
          />
        </Modal>
      )}

      {detailStudent && <StudentDetail data={data} student={detailStudent} onClose={() => setDetailId(null)} />}

      {remarkStudentId && (
        <Modal title={`Remark \u2014 ${data.students.find((x) => x.id === remarkStudentId)?.name || ""}`} onClose={() => setRemarkStudentId(null)}>
          <p className="sa-muted-text" style={{ whiteSpace: "pre-wrap" }}>{data.students.find((x) => x.id === remarkStudentId)?.remark}</p>
        </Modal>
      )}

      {confirmDelete && (
        <ConfirmDialog
          message="Delete this player? If they have any attendance or payment records, they can't be deleted until those are resolved — consider marking them Inactive instead."
          onCancel={() => setConfirmDelete(null)}
          onConfirm={() => remove(confirmDelete)}
        />
      )}

      {inactivityReviewOpen && (
        <InactivityReviewModal
          data={data}
          locationId={locationId}
          onClose={() => setInactivityReviewOpen(false)}
          refetchData={refetchData}
        />
      )}
    </div>
  );
}

/* ============================== ATTENDANCE ============================== */

function AttendancePage({ data, refetchData, locationId }) {
  const [date, setDate] = useState(todayISO());
  const [search, setSearch] = useState("");
  const [batchFilter, setBatchFilter] = useState("ALL");
  const [statusFilter, setStatusFilter] = useState("All");
  const [attendanceFilter, setAttendanceFilter] = useState("All");
  const [saveError, setSaveError] = useState(null);
  const [pendingStatus, setPendingStatus] = useState({});
  const pendingStatusRef = useRef({});

  const batchOptions = data.batches.filter((b) => locationId === "ALL" || b.locationId === locationId);

  const sessionFor = (student) =>
    data.sessions.find((s) => s.locationId === student.locationId && s.date === date && s.batchId === student.batchId);

  const statusFor = (student) => {
    if (Object.prototype.hasOwnProperty.call(pendingStatus, student.id)) return pendingStatus[student.id];
    const session = sessionFor(student);
    if (!session) return null;
    const rec = data.attendance.find((a) => a.sessionId === session.id && a.studentId === student.id);
    return rec ? rec.status : null;
  };

  const students = data.students.filter((s) => {
    if (locationId !== "ALL" && s.locationId !== locationId) return false;
    if (batchFilter !== "ALL" && s.batchId !== batchFilter) return false;
    if (statusFilter !== "All" && s.status !== statusFilter) return false;
    if (attendanceFilter !== "All") {
      const att = statusFor(s);
      if (attendanceFilter === "Present" && att !== "P") return false;
      if (attendanceFilter === "Absent" && att !== "A") return false;
      if (attendanceFilter === "NotMarked" && att) return false;
    }
    const q = search.trim().toLowerCase();
    if (!q) return true;
    return s.name.toLowerCase().includes(q) || (s.jerseyName || "").toLowerCase().includes(q) || String(s.jerseyNo).toLowerCase().includes(q);
  });

  const clearPendingIfCurrent = (studentId, status) => {
    if (pendingStatusRef.current[studentId] !== status) return;
    const next = { ...pendingStatusRef.current };
    delete next[studentId];
    pendingStatusRef.current = next;
    setPendingStatus(next);
  };

  const markStatus = async (student, status) => {
    pendingStatusRef.current = { ...pendingStatusRef.current, [student.id]: status };
    setPendingStatus(pendingStatusRef.current);

    let session = data.sessions.find((s) => s.locationId === student.locationId && s.date === date && s.batchId === student.batchId);
    let sessionId = session?.id;
    if (!sessionId) {
      const { data: created, error } = await supabase.from("sessions").insert({
        location_id: student.locationId, batch_id: student.batchId, date, start_time: "00:00", end_time: "00:00",
      }).select().single();
      if (error) {
        setSaveError(error.message);
        clearPendingIfCurrent(student.id, status);
        return;
      }
      sessionId = created.id;
    }

    // A newer click for this student has already taken over — let that call own the write.
    if (pendingStatusRef.current[student.id] !== status) return;

    const { error } = await supabase
      .from("attendance")
      .upsert({ session_id: sessionId, student_id: student.id, status }, { onConflict: "session_id,student_id" });
    if (error) {
      setSaveError(error.message);
      clearPendingIfCurrent(student.id, status);
      return;
    }
    setSaveError(null);

    if (pendingStatusRef.current[student.id] !== status) return;

    await refetchData();
    clearPendingIfCurrent(student.id, status);
  };

  const presentCount = students.filter((s) => statusFor(s) === "P").length;

  return (
    <div className="sa-page">
      {saveError && <div className="sa-storage-warning"><AlertCircle size={14} /> {saveError}</div>}
      <div className="sa-page-actions">
        <div className="sa-search-row">
          <div className="sa-search-box" style={{ minWidth: "min(420px, 100%)" }}>
            <Search size={15} />
            <input placeholder="Search by name, jersey name, or jersey no." value={search} onChange={(e) => setSearch(e.target.value)} autoComplete="off" autoCorrect="off" autoCapitalize="off" spellCheck={false} />
            {search && <SearchClearButton onClear={() => setSearch("")} />}
          </div>
          <select className="sa-inline-select" value={batchFilter} onChange={(e) => setBatchFilter(e.target.value)}>
            <option value="ALL">All Batches</option>
            {batchOptions.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
          </select>
          <select className="sa-inline-select" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option>All</option><option>Active</option><option>Inactive</option>
          </select>
          <select className="sa-inline-select" value={attendanceFilter} onChange={(e) => setAttendanceFilter(e.target.value)}>
            <option value="All">All Attendance</option>
            <option value="Present">Present</option>
            <option value="Absent">Absent</option>
            <option value="NotMarked">Not Marked</option>
          </select>
          <DateInput className="sa-inline-select sa-att-date" value={date} onChange={(e) => setDate(e.target.value)} />
        </div>
      </div>

      <div className="sa-scoreboard">
        <ScoreCard label="Players Present" value={presentCount} sub={`of ${students.length} shown for ${fmtDate(date)}`} icon={Check} accent="var(--teal)" />
      </div>

      {students.length === 0 ? (
        <EmptyState icon={ClipboardList} title="No players found" message="Try adjusting filters." />
      ) : (
        <div className="sa-table-wrap sa-attendance-scroll">
          <table className="sa-table sa-table-compact sa-attendance-table">
            <thead>
              <tr>
                <th className="sa-col-name">Name</th><th>Jersey Name</th><th>Jersey No.</th><th>Fee Due</th><th>Batch</th>
                <th className="sa-th-center">Attendance</th>
              </tr>
            </thead>
            <tbody>
              {students.map((s) => {
                const status = statusFor(s);
                const feeStatus = studentFeeStatus(data, s);
                return (
                  <tr key={s.id}>
                    <td className="sa-td-strong sa-col-name">{s.name}{s.status === "Inactive" && <Pill tone="red"> Inactive</Pill>}</td>
                    <td>{s.jerseyName || "\u2014"}</td>
                    <td>#{s.jerseyNo}</td>
                    <td><Pill tone={feeStatus === "Paid" ? "teal" : feeStatus === "Overdue" ? "red" : "amber"}>{feeStatus}</Pill></td>
                    <td>{batchName(data, s.batchId)}</td>
                    <td className="sa-th-center">
                      <div className="sa-att-toggle">
                        <button
                          className={`sa-att-toggle-btn sa-att-toggle-p ${status === "P" ? "sa-att-toggle-active" : ""}`}
                          onClick={() => markStatus(s, "P")}
                          aria-label={`Mark ${s.name} present`}
                        >
                          <Check size={15} strokeWidth={3} />
                        </button>
                        <button
                          className={`sa-att-toggle-btn sa-att-toggle-a ${status === "A" ? "sa-att-toggle-active" : ""}`}
                          onClick={() => markStatus(s, "A")}
                          aria-label={`Mark ${s.name} absent`}
                        >
                          <X size={15} strokeWidth={3} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

/* ============================== COACHES ============================== */

function CoachForm({ data, initial, submitting, onCancel, onSave }) {
  const [form, setForm] = useState(initial);
  const toggleLoc = (id) => {
    setForm((f) => ({
      ...f,
      locationIds: f.locationIds.includes(id) ? f.locationIds.filter((x) => x !== id) : [...f.locationIds, id],
    }));
  };
  return (
    <div className="sa-form">
      <div className="sa-form-row">
        <Field label="Coach Name">
          <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Full name" />
        </Field>
        <Field label="Specialty">
          <input value={form.specialty} onChange={(e) => setForm({ ...form, specialty: e.target.value })} placeholder="e.g. Football" />
        </Field>
      </div>
      <div className="sa-form-row">
        <Field label="Phone">
          <input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="+971 ..." />
        </Field>
        <Field label="Email">
          <input value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="name@example.com" />
        </Field>
      </div>
      <Field label="Assigned Locations">
        <div className="sa-checkbox-group">
          {data.locations.map((l) => (
            <label key={l.id} className="sa-checkbox">
              <input type="checkbox" checked={form.locationIds.includes(l.id)} onChange={() => toggleLoc(l.id)} />
              {l.name}
            </label>
          ))}
        </div>
      </Field>
      <div className="sa-form-actions">
        <button className="sa-btn sa-btn-ghost" disabled={submitting} onClick={onCancel}>Cancel</button>
        <button className="sa-btn sa-btn-primary" disabled={submitting} onClick={() => { if (form.name.trim() && !submitting) onSave(form); }}>
          {submitting ? "Saving…" : "Save Coach"}
        </button>
      </div>
    </div>
  );
}

function CoachesPage({ data, refetchData, locationId }) {
  const [modal, setModal] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [viewSessionsFor, setViewSessionsFor] = useState(null);
  const [saveError, setSaveError] = useState(null);
  const [saving, setSaving] = useState(false);
  const savingRef = useRef(false);
  const blank = { name: "", phone: "", email: "", specialty: "", locationIds: locationId === "ALL" ? [] : [locationId] };

  const coaches = data.coaches.filter((c) => locationId === "ALL" || c.locationIds.includes(locationId));

  const openAdd = () => setModal({ mode: "add" });
  const openEdit = (c) => setModal({ mode: "edit", id: c.id, initial: c });

  const save = async (form) => {
    if (savingRef.current) return;
    savingRef.current = true;
    setSaving(true);
    try {
      const payload = { name: form.name, phone: form.phone, email: form.email, specialty: form.specialty };
      let coachId = modal.id;
      if (modal.mode === "add") {
        const { data: created, error } = await supabase.from("coaches").insert(payload).select().single();
        if (error) { setSaveError(error.message); return; }
        coachId = created.id;
      } else {
        const { error } = await supabase.from("coaches").update(payload).eq("id", coachId);
        if (error) { setSaveError(error.message); return; }
        await supabase.from("coach_locations").delete().eq("coach_id", coachId);
      }
      if (form.locationIds.length > 0) {
        const { error } = await supabase.from("coach_locations").insert(
          form.locationIds.map((location_id) => ({ coach_id: coachId, location_id }))
        );
        if (error) { setSaveError(error.message); return; }
      }
      setSaveError(null);
      await refetchData();
      setModal(null);
    } finally {
      savingRef.current = false;
      setSaving(false);
    }
  };
  const remove = async (id) => {
    const { error } = await supabase.from("coaches").delete().eq("id", id);
    if (error) { setSaveError(friendlyDeleteError(error, "coach")); setConfirmDelete(null); return; }
    setSaveError(null);
    await refetchData();
    setConfirmDelete(null);
  };

  const sessionsCoach = data.coaches.find((c) => c.id === viewSessionsFor);
  const coachSessions = sessionsCoach ? data.sessions.filter((s) => (s.coachIds || []).includes(sessionsCoach.id)).sort((a, b) => (a.date < b.date ? 1 : -1)) : [];

  return (
    <div className="sa-page">
      <div className="sa-page-actions">
        <div />
        <button className="sa-btn sa-btn-primary" onClick={openAdd}><Plus size={16} /> Add Coach</button>
      </div>

      {coaches.length === 0 ? (
        <EmptyState icon={Users} title="No coaches" message="Add a coach for this location." />
      ) : (
        <div className="sa-card-grid">
          {coaches.map((c) => {
            const sessionCount = data.sessions.filter((s) => (s.coachIds || []).includes(c.id)).length;
            return (
              <div key={c.id} className="sa-loc-card">
                <div className="sa-loc-card-top">
                  <div className="sa-loc-icon" style={{ background: "#0F1B2D" }}><Users size={16} color="#FFB020" /></div>
                  <div className="sa-loc-card-actions">
                    <button className="sa-icon-btn" onClick={() => openEdit(c)}><Pencil size={14} /></button>
                    <button className="sa-icon-btn" onClick={() => setConfirmDelete(c.id)}><Trash2 size={14} /></button>
                  </div>
                </div>
                <h3>{c.name}</h3>
                <p className="sa-loc-address">{c.specialty || "General coaching"}</p>
                <div className="sa-loc-meta">
                  <span><Phone size={12} /> {c.phone}</span>
                  <span><Mail size={12} /> {c.email}</span>
                </div>
                <div className="sa-loc-meta">
                  {c.locationIds.map((lid) => <Pill key={lid} tone="neutral">{locationName(data, lid)}</Pill>)}
                </div>
                <button className="sa-btn sa-btn-ghost sa-btn-sm" onClick={() => setViewSessionsFor(c.id)}>
                  <ClipboardList size={14} /> {sessionCount} assigned sessions
                </button>
              </div>
            );
          })}
        </div>
      )}

      {modal && (
        <Modal title={modal.mode === "add" ? "Add Coach" : "Edit Coach"} onClose={() => setModal(null)}>
          {saveError && <div className="sa-login-error"><AlertCircle size={14} /> {saveError}</div>}
          <CoachForm data={data} initial={modal.mode === "add" ? blank : modal.initial} submitting={saving} onCancel={() => setModal(null)} onSave={save} />
        </Modal>
      )}

      {sessionsCoach && (
        <Modal title={`Sessions \u2014 ${sessionsCoach.name}`} onClose={() => setViewSessionsFor(null)}>
          {coachSessions.length === 0 ? (
            <p className="sa-muted-text">No sessions assigned yet.</p>
          ) : (
            <div className="sa-table-wrap">
              <table className="sa-table sa-table-compact">
                <thead><tr><th>Date</th><th>Time</th><th>Batch</th><th>Location</th></tr></thead>
                <tbody>
                  {coachSessions.map((s) => (
                    <tr key={s.id}>
                      <td>{fmtDate(s.date)}</td><td>{s.startTime}{"\u2013"}{s.endTime}</td><td>{batchName(data, s.batchId)}</td><td>{locationName(data, s.locationId)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </Modal>
      )}

      {confirmDelete && (
        <ConfirmDialog message="Delete this coach?" onCancel={() => setConfirmDelete(null)} onConfirm={() => remove(confirmDelete)} />
      )}
    </div>
  );
}

/* ============================== TRAINING SCHEDULES ============================== */

function SessionForm({ data, locationId, date, initial, submitting, onCancel, onSave }) {
  const isEdit = !!initial;
  const [form, setForm] = useState(
    initial
      ? { ...initial, batchIds: [initial.batchId] }
      : { date, startTime: "16:00", endTime: "17:00", batchIds: [], coachIds: [] }
  );
  const batchOptions = data.batches.filter((b) => b.locationId === locationId);
  const coachOptions = data.coaches.filter((c) => c.locationIds.includes(locationId));
  const toggleBatch = (id) => {
    setForm((f) => ({
      ...f,
      batchIds: f.batchIds.includes(id) ? f.batchIds.filter((x) => x !== id) : [...f.batchIds, id],
    }));
  };
  const toggleCoach = (id) => {
    setForm((f) => ({
      ...f,
      coachIds: f.coachIds.includes(id) ? f.coachIds.filter((x) => x !== id) : [...f.coachIds, id],
    }));
  };
  const canSubmit = form.batchIds.length > 0;
  return (
    <div className="sa-form">
      <Field label="Date"><DateInput value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></Field>
      <div className="sa-form-row">
        <Field label="Start Time"><input type="time" value={form.startTime} onChange={(e) => setForm({ ...form, startTime: e.target.value })} /></Field>
        <Field label="End Time"><input type="time" value={form.endTime} onChange={(e) => setForm({ ...form, endTime: e.target.value })} /></Field>
      </div>
      <Field label="Batch">
        {isEdit ? (
          // Editing one existing session — it's still one row for one batch, so this
          // stays a single select. Multi-select only applies when creating new sessions.
          <select value={form.batchIds[0] || ""} onChange={(e) => setForm({ ...form, batchIds: [e.target.value] })}>
            <option value="">Select batch</option>
            {batchOptions.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
          </select>
        ) : (
          <div className="sa-checkbox-group">
            {batchOptions.map((b) => (
              <label key={b.id} className="sa-checkbox">
                <input type="checkbox" checked={form.batchIds.includes(b.id)} onChange={() => toggleBatch(b.id)} />
                {b.name}
              </label>
            ))}
          </div>
        )}
      </Field>
      {!isEdit && form.batchIds.length > 0 && (
        <p className="sa-muted-text">
          {form.batchIds.length} session{form.batchIds.length === 1 ? "" : "s"} will be created — one per batch, same date &amp; time.
        </p>
      )}
      <Field label="Coaches">
        {coachOptions.length === 0 ? (
          <p className="sa-muted-text">No coaches assigned to this location yet.</p>
        ) : (
          <div className="sa-checkbox-group">
            {coachOptions.map((c) => (
              <label key={c.id} className="sa-checkbox">
                <input type="checkbox" checked={form.coachIds.includes(c.id)} onChange={() => toggleCoach(c.id)} />
                {c.name}
              </label>
            ))}
          </div>
        )}
      </Field>
      <div className="sa-form-actions">
        <button className="sa-btn sa-btn-ghost" disabled={submitting} onClick={onCancel}>Cancel</button>
        <button
          className="sa-btn sa-btn-primary"
          disabled={!canSubmit || submitting}
          onClick={() => { if (canSubmit && !submitting) onSave(form); }}
        >
          {submitting ? "Saving…" : "Save Session"}
        </button>
      </div>
    </div>
  );
}

const WEEKDAYS = [
  { key: 1, label: "Mon" }, { key: 2, label: "Tue" }, { key: 3, label: "Wed" },
  { key: 4, label: "Thu" }, { key: 5, label: "Fri" }, { key: 6, label: "Sat" }, { key: 0, label: "Sun" },
];

function BulkSessionForm({ data, locationId, submitting, onCancel, onCreate }) {
  const today = todayISO();
  const [form, setForm] = useState({
    fromDate: today,
    toDate: today,
    startTime: "16:00",
    endTime: "17:00",
    batchIds: [],
    coachIds: [],
    days: [1, 2, 3, 4, 5, 6, 0],
  });
  const batchOptions = data.batches.filter((b) => b.locationId === locationId);
  const coachOptions = data.coaches.filter((c) => c.locationIds.includes(locationId));

  const toggleDay = (d) => {
    setForm((f) => ({ ...f, days: f.days.includes(d) ? f.days.filter((x) => x !== d) : [...f.days, d] }));
  };
  const toggleBatch = (id) => {
    setForm((f) => ({ ...f, batchIds: f.batchIds.includes(id) ? f.batchIds.filter((x) => x !== id) : [...f.batchIds, id] }));
  };
  const toggleCoach = (id) => {
    setForm((f) => ({ ...f, coachIds: f.coachIds.includes(id) ? f.coachIds.filter((x) => x !== id) : [...f.coachIds, id] }));
  };

  let previewDateCount = 0;
  if (form.fromDate && form.toDate && form.fromDate <= form.toDate) {
    let cur = form.fromDate;
    let guard = 0;
    while (cur <= form.toDate && guard < 400) {
      if (form.days.includes(parseISO(cur).getDay())) previewDateCount++;
      cur = addDays(cur, 1);
      guard++;
    }
  }
  const previewCount = previewDateCount * form.batchIds.length;

  const canSubmit = form.batchIds.length > 0 && form.fromDate && form.toDate && form.fromDate <= form.toDate && form.days.length > 0;

  return (
    <div className="sa-form">
      <div className="sa-form-row">
        <Field label="From Date"><DateInput value={form.fromDate} onChange={(e) => setForm({ ...form, fromDate: e.target.value })} /></Field>
        <Field label="To Date"><DateInput value={form.toDate} onChange={(e) => setForm({ ...form, toDate: e.target.value })} /></Field>
      </div>
      <div className="sa-form-row">
        <Field label="Start Time"><input type="time" value={form.startTime} onChange={(e) => setForm({ ...form, startTime: e.target.value })} /></Field>
        <Field label="End Time"><input type="time" value={form.endTime} onChange={(e) => setForm({ ...form, endTime: e.target.value })} /></Field>
      </div>
      <Field label="Repeat On">
        <div className="sa-checkbox-group">
          {WEEKDAYS.map((w) => (
            <label key={w.key} className="sa-checkbox">
              <input type="checkbox" checked={form.days.includes(w.key)} onChange={() => toggleDay(w.key)} />
              {w.label}
            </label>
          ))}
        </div>
      </Field>
      <Field label="Batch">
        <div className="sa-checkbox-group">
          {batchOptions.map((b) => (
            <label key={b.id} className="sa-checkbox">
              <input type="checkbox" checked={form.batchIds.includes(b.id)} onChange={() => toggleBatch(b.id)} />
              {b.name}
            </label>
          ))}
        </div>
      </Field>
      <Field label="Coaches">
        {coachOptions.length === 0 ? (
          <p className="sa-muted-text">No coaches assigned to this location yet.</p>
        ) : (
          <div className="sa-checkbox-group">
            {coachOptions.map((c) => (
              <label key={c.id} className="sa-checkbox">
                <input type="checkbox" checked={form.coachIds.includes(c.id)} onChange={() => toggleCoach(c.id)} />
                {c.name}
              </label>
            ))}
          </div>
        )}
      </Field>
      <p className="sa-muted-text">
        {previewCount} session{previewCount === 1 ? "" : "s"} will be created
        {form.batchIds.length > 1 ? ` (${previewDateCount} date${previewDateCount === 1 ? "" : "s"} × ${form.batchIds.length} batches)` : ""}.
      </p>
      <div className="sa-form-actions">
        <button className="sa-btn sa-btn-ghost" disabled={submitting} onClick={onCancel}>Cancel</button>
        <button
          className="sa-btn sa-btn-primary"
          disabled={!canSubmit || submitting}
          onClick={() => { if (canSubmit && !submitting) onCreate(form); }}
        >
          {submitting ? "Creating…" : "Create Sessions"}
        </button>
      </div>
    </div>
  );
}

function AttendanceModal({ data, refetchData, session, onClose }) {
  const roster = data.students.filter((s) => s.batchId === session.batchId);
  const getStatus = (studentId) => {
    const rec = data.attendance.find((a) => a.sessionId === session.id && a.studentId === studentId);
    return rec ? rec.status : null;
  };
  const setStatus = async (studentId, status) => {
    await supabase
      .from("attendance")
      .upsert({ session_id: session.id, student_id: studentId, status }, { onConflict: "session_id,student_id" });
    await refetchData();
  };
  return (
    <Modal title={`Attendance \u2014 ${batchName(data, session.batchId)} \u00b7 ${fmtDate(session.date)}`} onClose={onClose}>
      {roster.length === 0 ? (
        <p className="sa-muted-text">No players in this batch yet.</p>
      ) : (
        <div className="sa-attendance-list">
          {roster.map((s) => {
            const status = getStatus(s.id);
            return (
              <div key={s.id} className="sa-attendance-row">
                <div className="sa-attendance-name"><JerseyBadge no={s.jerseyNo} size={28} /> {s.name}</div>
                <div className="sa-attendance-toggle">
                  <button className={`sa-att-btn ${status === "P" ? "sa-att-btn-p" : ""}`} onClick={() => setStatus(s.id, "P")}>Present</button>
                  <button className={`sa-att-btn ${status === "A" ? "sa-att-btn-a" : ""}`} onClick={() => setStatus(s.id, "A")}>Absent</button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </Modal>
  );
}

function SchedulesPage({ data, refetchData, locationId }) {
  const [mode, setMode] = useState("month");
  const [anchor, setAnchor] = useState(todayISO());
  const [selectedDay, setSelectedDay] = useState(todayISO());
  const [sessionModal, setSessionModal] = useState(null);
  const [attendanceSession, setAttendanceSession] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [bulkModal, setBulkModal] = useState(false);
  const [bulkResult, setBulkResult] = useState(null);
  const [bulkSubmitting, setBulkSubmitting] = useState(false);
  const bulkSubmittingRef = useRef(false); // synchronous guard — state updates aren't visible until the next render, so a second click before then would still slip through on state alone
  const [sessionSubmitting, setSessionSubmitting] = useState(false);
  const sessionSubmittingRef = useRef(false); // same reentrancy guard as bulk create — Add Session can now write several rows too
  const [saveError, setSaveError] = useState(null);

  if (!locationId) return <EmptyState icon={CalendarIcon} title="No location selected" message="Add a location first." />;

  const locSessions = data.sessions.filter((s) => s.locationId === locationId);
  const sessionsByDate = (d) => locSessions.filter((s) => s.date === d).sort((a, b) => (a.startTime || "").localeCompare(b.startTime || ""));

  const { days, first, last } = monthMode();
  function monthMode() {
    if (mode === "month") return monthDays(anchor);
    return { days: weekDays(anchor), first: null, last: null };
  }

  const shift = (n) => {
    if (mode === "month") setAnchor(shiftMonths(anchor, n));
    else setAnchor(addDays(anchor, 7 * n));
  };

  const removeSession = async (id) => {
    // Re-check against live data (not just what the trash button saw) in case
    // attendance was marked for this session in the moment before confirming.
    if (sessionHasPresentAttendance(data, id)) {
      setSaveError("This session has players marked Present and can't be deleted.");
      setConfirmDelete(null);
      return;
    }
    const { error } = await supabase.from("sessions").delete().eq("id", id);
    if (error) { setSaveError(friendlyDeleteError(error, "session")); setConfirmDelete(null); return; }
    setSaveError(null);
    await refetchData();
    setConfirmDelete(null);
  };

  const saveSession = async (form) => {
    if (sessionSubmittingRef.current) return;
    sessionSubmittingRef.current = true;
    setSessionSubmitting(true);
    try {
      if (sessionModal.mode === "add") {
        // One row per selected batch — same date/time/location/coaches, so
        // checking U6 + U8 + U10 writes three ordinary session rows in one go.
        const { data: created, error } = await supabase
          .from("sessions")
          .insert(form.batchIds.map((batchId) => ({
            location_id: locationId, batch_id: batchId, date: form.date,
            start_time: form.startTime, end_time: form.endTime,
          })))
          .select();
        if (error) { setSaveError(error.message); return; }
        if (form.coachIds.length > 0) {
          const rows = created.flatMap((s) => form.coachIds.map((coach_id) => ({ session_id: s.id, coach_id })));
          const { error: cErr } = await supabase.from("session_coaches").insert(rows);
          if (cErr) { setSaveError(cErr.message); return; }
        }
      } else {
        // Editing one existing session — still exactly one batch, one row.
        const sessionId = sessionModal.id;
        const payload = {
          location_id: locationId, batch_id: form.batchIds[0], date: form.date,
          start_time: form.startTime, end_time: form.endTime,
        };
        const { error } = await supabase.from("sessions").update(payload).eq("id", sessionId);
        if (error) { setSaveError(error.message); return; }
        await supabase.from("session_coaches").delete().eq("session_id", sessionId);
        if (form.coachIds.length > 0) {
          const { error: cErr } = await supabase.from("session_coaches").insert(
            form.coachIds.map((coach_id) => ({ session_id: sessionId, coach_id }))
          );
          if (cErr) { setSaveError(cErr.message); return; }
        }
      }
      setSaveError(null);
      await refetchData();
      setSessionModal(null);
    } finally {
      sessionSubmittingRef.current = false;
      setSessionSubmitting(false);
    }
  };

  const createBulkSessions = async (form) => {
    // Guard against duplicate submissions from repeated/rapid clicks on "Create
    // Sessions" — the ref is checked synchronously so a second click fired before
    // the first render (i.e. before bulkSubmitting state is visible) is still caught.
    if (bulkSubmittingRef.current) return;
    bulkSubmittingRef.current = true;
    setBulkSubmitting(true);
    try {
      const dates = [];
      let cur = form.fromDate;
      let guard = 0;
      while (cur <= form.toDate && guard < 400) {
        if (form.days.includes(parseISO(cur).getDay())) dates.push(cur);
        cur = addDays(cur, 1);
        guard++;
      }
      // Cross-product of dates × selected batches, skipping any (date, batch)
      // pair that already has a matching session — de-duped within this run too.
      const seen = new Set();
      const toCreate = [];
      for (const date of dates) {
        for (const batchId of form.batchIds) {
          const key = `${date}|${batchId}`;
          const exists = data.sessions.some(
            (s) => s.locationId === locationId && s.date === date && s.batchId === batchId && s.startTime === form.startTime
          );
          if (!exists && !seen.has(key)) {
            toCreate.push({ date, batchId });
            seen.add(key);
          }
        }
      }
      if (toCreate.length === 0) {
        setBulkResult(0);
        return;
      }
      const { data: created, error } = await supabase
        .from("sessions")
        .insert(toCreate.map(({ date, batchId }) => ({
          location_id: locationId, batch_id: batchId, date,
          start_time: form.startTime, end_time: form.endTime,
        })))
        .select();
      if (error) { setSaveError(error.message); return; }
      if (form.coachIds.length > 0) {
        const rows = created.flatMap((s) => form.coachIds.map((coach_id) => ({ session_id: s.id, coach_id })));
        const { error: cErr } = await supabase.from("session_coaches").insert(rows);
        if (cErr) { setSaveError(cErr.message); return; }
      }
      setSaveError(null);
      await refetchData();
      setBulkResult(created.length);
    } finally {
      bulkSubmittingRef.current = false;
      setBulkSubmitting(false);
    }
  };

  const daySessions = sessionsByDate(selectedDay);

  return (
    <div className="sa-page">
      {saveError && <div className="sa-storage-warning"><AlertCircle size={14} /> {saveError}</div>}
      <div className="sa-schedule-toolbar">
        <div className="sa-schedule-nav">
          <button className="sa-icon-btn" onClick={() => shift(-1)}><ChevronLeft size={16} /></button>
          <span className="sa-schedule-label">
            {mode === "month" ? parseISO(startOfMonth(anchor)).toLocaleDateString("en-US", { month: "long", year: "numeric" }) : `Week of ${fmtDateShort(startOfWeek(anchor))}`}
          </span>
          <button className="sa-icon-btn" onClick={() => shift(1)}><ChevronRight size={16} /></button>
          <button className="sa-btn sa-btn-ghost sa-btn-sm" onClick={() => { setAnchor(todayISO()); setSelectedDay(todayISO()); }}>Today</button>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <button className="sa-btn sa-btn-ghost sa-btn-sm" onClick={() => setBulkModal(true)}><Plus size={14} /> Bulk Create Sessions</button>
          <div className="sa-view-toggle">
            <button className={mode === "week" ? "sa-toggle-active" : ""} onClick={() => setMode("week")}>Week</button>
            <button className={mode === "month" ? "sa-toggle-active" : ""} onClick={() => setMode("month")}>Month</button>
          </div>
        </div>
      </div>

      <div className={`sa-calendar ${mode === "week" ? "sa-calendar-week" : ""}`}>
        <div className="sa-calendar-weekdays">
          {["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((d) => <div key={d}>{d}</div>)}
        </div>
        <div className={`sa-calendar-grid ${mode === "week" ? "sa-calendar-grid-week" : ""}`}>
          {days.map((d) => {
            const items = sessionsByDate(d);
            const inMonth = mode === "week" || monthKey(d) === monthKey(anchor);
            return (
              <div
                key={d}
                className={`sa-calendar-cell ${d === selectedDay ? "sa-calendar-cell-selected" : ""} ${d === todayISO() ? "sa-calendar-cell-today" : ""} ${!inMonth ? "sa-calendar-cell-out" : ""}`}
                onClick={() => setSelectedDay(d)}
              >
                <span className="sa-calendar-daynum">{parseISO(d).getDate()}</span>
                <div className="sa-calendar-chips">
                  {items.slice(0, mode === "week" ? 6 : 2).map((s) => (
                    <div key={s.id} className="sa-calendar-chip">
                      <div className="sa-calendar-chip-time">{s.startTime} - {s.endTime}</div>
                      <div className="sa-calendar-chip-batch">{batchName(data, s.batchId)}</div>
                    </div>
                  ))}
                  {mode === "month" && items.length > 2 && <div className="sa-calendar-more">+{items.length - 2} more</div>}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="sa-day-panel">
        <div className="sa-day-panel-head">
          <h3>{fmtDate(selectedDay)}</h3>
          <button className="sa-btn sa-btn-primary sa-btn-sm" onClick={() => setSessionModal({ mode: "add" })}><Plus size={14} /> Add Session</button>
        </div>
        {daySessions.length === 0 ? (
          <p className="sa-muted-text">No sessions scheduled. Add one to assign a coach and batch.</p>
        ) : (
          <div className="sa-session-list">
            {daySessions.map((s) => (
              <div key={s.id} className="sa-session-row">
                <div className="sa-session-time">{s.startTime} - {s.endTime}</div>
                <div className="sa-session-info">
                  <strong>{batchName(data, s.batchId)}</strong>
                  <span>Coach: {coachNames(data, s.coachIds)}</span>
                </div>
                <div className="sa-session-actions">
                  <button className="sa-btn sa-btn-ghost sa-btn-sm" onClick={() => setAttendanceSession(s)}><Check size={14} /> Attendance</button>
                  <button className="sa-icon-btn" onClick={() => setSessionModal({ mode: "edit", id: s.id, initial: s })}><Pencil size={14} /></button>
                  <button
                    className="sa-icon-btn"
                    title={sessionHasPresentAttendance(data, s.id) ? "Can't delete — players are marked Present for this session" : "Delete session"}
                    onClick={() => {
                      if (sessionHasPresentAttendance(data, s.id)) {
                        setSaveError("This session has players marked Present and can't be deleted.");
                        return;
                      }
                      setSaveError(null);
                      setConfirmDelete(s.id);
                    }}
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {sessionModal && (
        <Modal title={sessionModal.mode === "add" ? "Add Session" : "Edit Session"} onClose={() => setSessionModal(null)}>
          <SessionForm data={data} locationId={locationId} date={selectedDay} initial={sessionModal.initial} submitting={sessionSubmitting} onCancel={() => setSessionModal(null)} onSave={saveSession} />
        </Modal>
      )}

      {attendanceSession && (
        <AttendanceModal data={data} refetchData={refetchData} session={attendanceSession} onClose={() => setAttendanceSession(null)} />
      )}

      {confirmDelete && (
        <ConfirmDialog message="Delete this session and its attendance records?" onCancel={() => setConfirmDelete(null)} onConfirm={() => removeSession(confirmDelete)} />
      )}

      {bulkModal && (
        <Modal title="Create Multiple Sessions" onClose={() => { setBulkModal(false); setBulkResult(null); }}>
          {bulkResult === null ? (
            <BulkSessionForm data={data} locationId={locationId} submitting={bulkSubmitting} onCancel={() => setBulkModal(false)} onCreate={createBulkSessions} />
          ) : (
            <div className="sa-form">
              <p className="sa-muted-text">{bulkResult} session{bulkResult === 1 ? "" : "s"} created successfully.</p>
              <div className="sa-form-actions">
                <button className="sa-btn sa-btn-primary" onClick={() => { setBulkModal(false); setBulkResult(null); }}>Done</button>
              </div>
            </div>
          )}
        </Modal>
      )}
    </div>
  );
}

/* ============================== FEE UPDATE ============================== */

const PAYMENT_TYPES = ["Fee", "Extra Jersey", "Full Kit"];
const PAYMENT_MODES = ["Cash", "Card", "Bank Transfer", "Payment Link"];
const PAYMENT_MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

function RecordPaymentForm({ initial, submitting, onCancel, onSave }) {
  const [form, setForm] = useState(initial || {
    paymentType: "Fee", paymentMode: "", paymentMonth: "", date: todayISO(), receiptNo: "", amount: "", nextPaymentDate: "",
    startDate: "", endDate: "", registrationFeeAmount: "", comment: "",
  });
  const isFee = form.paymentType === "Fee";

  // Payment Month is stored as "MM/YYYY" so it's unambiguous across years; the
  // UI still shows it as a month-name dropdown (unchanged) plus a year dropdown.
  const currentYear = new Date().getFullYear();
  const [pmMonthNum, pmYearStr] = (form.paymentMonth || "").split("/");
  const pmMonthName = pmMonthNum ? (PAYMENT_MONTHS[Number(pmMonthNum) - 1] || "") : "";
  const pmYear = pmYearStr || String(currentYear);
  const PAYMENT_YEARS = Array.from({ length: 7 }, (_, i) => String(currentYear - 5 + i));
  const setPmMonthName = (name) => {
    const mm = String(PAYMENT_MONTHS.indexOf(name) + 1).padStart(2, "0");
    setForm({ ...form, paymentMonth: `${mm}/${pmYear}` });
  };
  const setPmYear = (year) => {
    setForm({ ...form, paymentMonth: `${pmMonthNum || ""}/${year}` });
  };
  const paymentMonthValid = /^(0[1-9]|1[0-2])\/\d{4}$/.test(form.paymentMonth || "");

  const canSave = form.paymentType && form.paymentMode && paymentMonthValid && form.date && form.receiptNo.trim() && form.amount !== ""
    && (!isFee || (form.startDate && form.endDate && form.nextPaymentDate));

  // End Date is derived from Next Payment Date and isn't directly editable.
  useEffect(() => {
    setForm((f) => ({ ...f, endDate: f.nextPaymentDate ? addDays(f.nextPaymentDate, -1) : "" }));
  }, [form.nextPaymentDate]);

  const handleSave = () => {
    if (canSave && !submitting) onSave(form);
  };

  return (
    <div className="sa-form">
      <div className="sa-form-row">
        <Field label="Payment Type" required>
          <select value={form.paymentType} onChange={(e) => setForm({ ...form, paymentType: e.target.value })}>
            {PAYMENT_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
          </select>
        </Field>
        <Field label="Payment Mode" required>
          <select value={form.paymentMode} onChange={(e) => setForm({ ...form, paymentMode: e.target.value })}>
            <option value="" disabled>Select mode…</option>
            {PAYMENT_MODES.map((m) => <option key={m} value={m}>{m}</option>)}
          </select>
        </Field>
      </div>

      <div className="sa-form-row">
        <Field label="Payment Date" required><DateInput value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></Field>
        <Field label="Payment Month" required>
          <div className="sa-form-row" style={{ gap: 8 }}>
            <select value={pmMonthName} onChange={(e) => setPmMonthName(e.target.value)}>
              <option value="" disabled>Select month…</option>
              {PAYMENT_MONTHS.map((m) => <option key={m} value={m}>{m}</option>)}
            </select>
            <select value={pmYear} onChange={(e) => setPmYear(e.target.value)}>
              {PAYMENT_YEARS.map((y) => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>
        </Field>
      </div>

      {isFee ? (
        <>
          <div className="sa-form-row">
            <Field label={`Registration Fee Amount (${CURRENCY})`}><input type="number" min="0" value={form.registrationFeeAmount} onChange={(e) => setForm({ ...form, registrationFeeAmount: e.target.value })} /></Field>
            <Field label={`Session Fee Amount (${CURRENCY})`} required><input type="number" min="0" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} /></Field>
          </div>
          <div className="sa-form-row">
            <Field label="Start Date" required><DateInput value={form.startDate} onChange={(e) => setForm({ ...form, startDate: e.target.value })} /></Field>
            <Field label="End Date" required>
              <input value={form.endDate ? fmtDate(form.endDate) : ""} readOnly />
            </Field>
          </div>
          <div className="sa-form-row">
            <Field label="Receipt No." required><input value={form.receiptNo} onChange={(e) => setForm({ ...form, receiptNo: e.target.value })} placeholder="RC-1000" /></Field>
            <Field label="Next Payment Date" required><DateInput value={form.nextPaymentDate} onChange={(e) => setForm({ ...form, nextPaymentDate: e.target.value })} /></Field>
          </div>
        </>
      ) : (
        <div className="sa-form-row">
          <Field label="Receipt No." required><input value={form.receiptNo} onChange={(e) => setForm({ ...form, receiptNo: e.target.value })} placeholder="RC-1000" /></Field>
          <Field label={`Payment Amount (${CURRENCY})`} required><input type="number" min="0" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} /></Field>
        </div>
      )}

      <Field label="Comments (optional)">
        <textarea rows={2} value={form.comment || ""} onChange={(e) => setForm({ ...form, comment: e.target.value })} placeholder="Any note about this payment" />
      </Field>

      <div className="sa-form-actions">
        <button className="sa-btn sa-btn-ghost" onClick={onCancel} disabled={submitting}>Cancel</button>
        <button className="sa-btn sa-btn-primary" disabled={!canSave || submitting} onClick={handleSave}>
          {submitting ? "Saving…" : (initial ? "Save Changes" : "Record Payment")}
        </button>
      </div>
    </div>
  );
}

function FeeUpdatePage({ data, refetchData, locationId }) {
  const [search, setSearch] = useState("");
  const [selectedId, setSelectedId] = useState(null);
  const [payModal, setPayModal] = useState(false);
  const [showBulk, setShowBulk] = useState(false);
  const [showPaid, setShowPaid] = useState(false);
  const [editingPayment, setEditingPayment] = useState(null);
  const [viewCommentPayment, setViewCommentPayment] = useState(null);
  const [saveError, setSaveError] = useState(null);
  const [successMessage, setSuccessMessage] = useState(null);
  const [paySubmitting, setPaySubmitting] = useState(false);
  const paySubmittingRef = useRef(false); // shared by record + update — only one of those modals is ever open at once

  useEffect(() => {
    if (!successMessage) return;
    const t = setTimeout(() => setSuccessMessage(null), 4000);
    return () => clearTimeout(t);
  }, [successMessage]);

  if (!locationId) return <EmptyState icon={Receipt} title="No location selected" message="Add a location first." />;

  const students = data.students.filter((s) => s.locationId === locationId);
  const q = search.trim().toLowerCase();
  const matches = q ? students.filter((s) => s.name.toLowerCase().includes(q) || (s.jerseyName || "").toLowerCase().includes(q) || String(s.jerseyNo).toLowerCase().includes(q)) : [];
  const selected = students.find((s) => s.id === selectedId);

  const sessionsSinceNextDue = selected ? sessionsOverdueCountFor(data, selected) : 0;

  const recordPayment = async (form) => {
    if (paySubmittingRef.current) return;
    paySubmittingRef.current = true;
    setPaySubmitting(true);
    try {
      const isFee = form.paymentType === "Fee";
      const { error } = await supabase.from("payments").insert({
        student_id: selected.id, date: form.date, receipt_no: form.receiptNo,
        amount: Number(form.amount), next_payment_date: isFee ? (form.nextPaymentDate || null) : null,
        comment: form.comment || null, payment_type: form.paymentType, payment_mode: form.paymentMode,
        payment_month: form.paymentMonth,
        start_date: isFee ? (form.startDate || null) : null, end_date: isFee ? (form.endDate || null) : null,
        registration_fee_amount: isFee && form.registrationFeeAmount !== "" ? Number(form.registrationFeeAmount) : null,
      });
      if (error) { setSaveError(error.message); return; }
      setSaveError(null);
      await refetchData();
      setPayModal(false);
      setSuccessMessage("Payment recorded successfully.");
    } finally {
      paySubmittingRef.current = false;
      setPaySubmitting(false);
    }
  };

  const updateLastPayment = async (form) => {
    if (paySubmittingRef.current) return;
    paySubmittingRef.current = true;
    setPaySubmitting(true);
    try {
      const isFee = form.paymentType === "Fee";
      const { error } = await supabase
        .from("payments")
        .update({
          date: form.date, receipt_no: form.receiptNo, amount: Number(form.amount),
          next_payment_date: isFee ? (form.nextPaymentDate || null) : null,
          comment: form.comment || null, payment_type: form.paymentType, payment_mode: form.paymentMode,
          payment_month: form.paymentMonth,
          start_date: isFee ? (form.startDate || null) : null, end_date: isFee ? (form.endDate || null) : null,
          registration_fee_amount: isFee && form.registrationFeeAmount !== "" ? Number(form.registrationFeeAmount) : null,
        })
        .eq("id", editingPayment.payment.id);
      if (error) { setSaveError(error.message); return; }
      setSaveError(null);
      await refetchData();
      setEditingPayment(null);
      setSuccessMessage("Payment updated successfully.");
    } finally {
      paySubmittingRef.current = false;
      setPaySubmitting(false);
    }
  };

  const pendingStudents = students
    .filter((s) => studentFeeStatus(data, s) !== "Paid")
    .map((s) => ({ s, status: studentFeeStatus(data, s), last: latestPayment(data, s.id), sessionsOverdue: sessionsOverdueCountFor(data, s) }))
    // Same isPendingForFees rule as the Reports > Pending Fees report and the dashboard's
    // outstanding figure, so all three stay in sync: a student whose next payment date is
    // more than 2 months back and who hasn't attended any session since is excluded here too.
    .filter(({ s }) => isPendingForFees(data, s));

  const paidStudents = students
    .filter((s) => studentFeeStatus(data, s) === "Paid")
    .map((s) => ({ s, last: latestPayment(data, s.id) }));

  return (
    <div className="sa-page">
      {saveError && <div className="sa-storage-warning"><AlertCircle size={14} /> {saveError}</div>}
      {successMessage && (
        <div className="sa-storage-warning" style={{ background: "#ECFDF5", color: "#047857", borderColor: "#A7F3D0" }}>
          <Check size={14} /> {successMessage}
        </div>
      )}
      <div className="sa-card">
        <div className="sa-card-header"><h3>Find a Player</h3></div>
        <div className="sa-search-box" style={{ maxWidth: 420 }}>
          <Search size={15} />
          <input placeholder="Search by name, jersey name, or jersey no." value={search} onChange={(e) => { setSearch(e.target.value); setSelectedId(null); }} autoComplete="off" autoCorrect="off" autoCapitalize="off" spellCheck={false} />
          {search && <SearchClearButton onClear={() => { setSearch(""); setSelectedId(null); }} />}
        </div>
        {q && matches.length > 0 && (
          <div className="sa-search-results">
            {matches.map((s) => (
              <div key={s.id} className="sa-search-result-row" onClick={() => { setSelectedId(s.id); setSearch(""); }}>
                <JerseyBadge no={s.jerseyNo} size={28} />
                <div><strong>{s.name}</strong><span> {"\u00b7"} {batchName(data, s.batchId)}</span></div>
              </div>
            ))}
          </div>
        )}
        {q && matches.length === 0 && <p className="sa-muted-text">No players match "{search}".</p>}
      </div>

      {selected && (
        <div className="sa-card" style={{ marginTop: 16 }}>
          <div className="sa-card-header">
            <h3>{selected.name}</h3>
            <Pill tone={studentFeeStatus(data, selected) === "Paid" ? "teal" : studentFeeStatus(data, selected) === "Overdue" ? "red" : "amber"}>
              {studentFeeStatus(data, selected)}
            </Pill>
          </div>
          <div className="sa-student-detail-grid" style={{ marginBottom: 12 }}>
            <div><span>Jersey</span><strong>#{selected.jerseyNo}</strong></div>
            <div><span>Batch</span><strong>{batchName(data, selected.batchId)}</strong></div>
            <div><span>Plan Fee</span><strong>{money(studentExpectedFee(data, selected))}</strong></div>
            <div><span>Next Due</span><strong>{fmtDate(latestPayment(data, selected.id)?.nextPaymentDate)}</strong></div>
            <div><span>No. of Sessions Overdue</span><strong>{sessionsSinceNextDue}</strong></div>
          </div>
          <button className="sa-btn sa-btn-primary" onClick={() => setPayModal(true)}><Plus size={16} /> Record Payment</button>

          <h4 className="sa-section-title">Fee History</h4>
          {studentPayments(data, selected.id).length === 0 ? (
            <p className="sa-muted-text">No payments recorded yet.</p>
          ) : (
            <div className="sa-table-wrap">
              <table className="sa-table sa-table-compact">
                <thead><tr><th>Date</th><th>Receipt No.</th><th>Mode</th><th>Amount</th><th>Next Due</th><th>Start Date</th><th>End Date</th><th></th><th></th></tr></thead>
                <tbody>
                  {studentPayments(data, selected.id).map((p, i) => (
                    <tr key={p.id}>
                      <td>{fmtDate(p.date)}</td><td className="sa-mono">{p.receiptNo}</td><td>{p.paymentMode || "—"}</td><td className="sa-mono">{money(p.amount)}</td><td>{fmtDate(p.nextPaymentDate)}</td><td>{p.startDate ? fmtDate(p.startDate) : "—"}</td><td>{p.endDate ? fmtDate(p.endDate) : "—"}</td>
                      <td>
                        {p.comment && p.comment.trim() ? (
                          <button className="sa-icon-btn" title="View comment" onClick={() => setViewCommentPayment(p)}><MessageSquare size={14} /></button>
                        ) : (
                          <span className="sa-icon-btn-placeholder" />
                        )}
                      </td>
                      <td>
                        {i === 0 ? (
                          <button className="sa-icon-btn" title="Edit latest payment" onClick={() => setEditingPayment({ student: selected, payment: p })}><Pencil size={14} /></button>
                        ) : (
                          <span className="sa-icon-btn-placeholder" />
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      <div className="sa-card" style={{ marginTop: 16 }}>
        <div className="sa-card-header">
          <h3>Pending &amp; Overdue Fees</h3>
          <button className="sa-icon-btn" onClick={() => setShowBulk(!showBulk)}>{showBulk ? "Hide" : "Show"}</button>
        </div>
        {showBulk && (
          pendingStudents.length === 0 ? (
            <p className="sa-muted-text">Everyone at this location is paid up.</p>
          ) : (
            <div className="sa-table-wrap">
              <table className="sa-table sa-table-compact">
                <thead><tr><th>Player</th><th>Jersey Name</th><th>Jersey No.</th><th>Batch</th><th>Status</th><th>Next Due</th><th>Amount Due</th><th>No. of Sessions Overdue</th></tr></thead>
                <tbody>
                  {pendingStudents.map(({ s, status, last, sessionsOverdue }) => (
                    <tr key={s.id} className="sa-row-clickable" onClick={() => setSelectedId(s.id)}>
                      <td className="sa-td-strong">{s.name}{s.status === "Inactive" && <Pill tone="red"> Inactive</Pill>}</td>
                      <td>{s.jerseyName || "\u2014"}</td>
                      <td>#{s.jerseyNo}</td>
                      <td>{batchName(data, s.batchId)}</td>
                      <td><Pill tone={status === "Overdue" ? "red" : "amber"}>{status}</Pill></td>
                      <td>{fmtDate(last?.nextPaymentDate)}</td>
                      <td className="sa-mono">{money(totalOverdueAmountFor(data, s))}</td>
                      <td className="sa-mono">{sessionsOverdue}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )
        )}
      </div>

      <div className="sa-card" style={{ marginTop: 16 }}>
        <div className="sa-card-header">
          <h3>Paid Fees</h3>
          <button className="sa-icon-btn" onClick={() => setShowPaid(!showPaid)}>{showPaid ? "Hide" : "Show"}</button>
        </div>
        {showPaid && (
          paidStudents.length === 0 ? (
            <p className="sa-muted-text">No paid players at this location yet.</p>
          ) : (
            <div className="sa-table-wrap">
              <table className="sa-table sa-table-compact">
                <thead><tr><th>Player</th><th>Jersey Name</th><th>Jersey No.</th><th>Batch</th><th>Amount Paid</th><th>Receipt No.</th><th>Next Due</th><th></th></tr></thead>
                <tbody>
                  {paidStudents.map(({ s, last }) => (
                    <tr key={s.id}>
                      <td className="sa-td-strong">{s.name}{s.status === "Inactive" && <Pill tone="red"> Inactive</Pill>}</td>
                      <td>{s.jerseyName || "\u2014"}</td>
                      <td>#{s.jerseyNo}</td>
                      <td>{batchName(data, s.batchId)}</td>
                      <td className="sa-mono">{money(last?.amount)}</td>
                      <td className="sa-mono">{last?.receiptNo}</td>
                      <td>{fmtDate(last?.nextPaymentDate)}</td>
                      <td className="sa-td-actions">
                        <button className="sa-btn sa-btn-ghost sa-btn-sm" onClick={() => setEditingPayment({ student: s, payment: last })}><Pencil size={14} /> Update</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )
        )}
      </div>

      {payModal && (
        <Modal title={`Record Payment \u2014 ${selected.name}`} onClose={() => setPayModal(false)}>
          <RecordPaymentForm submitting={paySubmitting} onCancel={() => setPayModal(false)} onSave={recordPayment} />
        </Modal>
      )}

      {editingPayment && (
        <Modal title={`Update Last Payment \u2014 ${editingPayment.student.name}`} onClose={() => setEditingPayment(null)}>
          <RecordPaymentForm
            initial={{
              paymentType: editingPayment.payment.paymentType || "Fee",
              paymentMode: editingPayment.payment.paymentMode || "",
              paymentMonth: editingPayment.payment.paymentMonth || "",
              date: editingPayment.payment.date,
              receiptNo: editingPayment.payment.receiptNo,
              amount: editingPayment.payment.amount,
              nextPaymentDate: editingPayment.payment.nextPaymentDate,
              startDate: editingPayment.payment.startDate || "",
              endDate: editingPayment.payment.endDate || "",
              registrationFeeAmount: editingPayment.payment.registrationFeeAmount ?? "",
              comment: editingPayment.payment.comment || "",
            }}
            submitting={paySubmitting}
            onCancel={() => setEditingPayment(null)}
            onSave={updateLastPayment}
          />
        </Modal>
      )}

      {viewCommentPayment && (
        <Modal title={`Comment \u2014 Receipt ${viewCommentPayment.receiptNo}`} onClose={() => setViewCommentPayment(null)}>
          <p className="sa-muted-text" style={{ whiteSpace: "pre-wrap" }}>{viewCommentPayment.comment}</p>
        </Modal>
      )}
    </div>
  );
}

/* ============================== REPORTS ============================== */

const REPORT_TABS = [
  { id: "studentSummary", label: "Player Fee & Attendance" },
  { id: "attendance", label: "Attendance by Location" },
  { id: "feeList", label: "Fee List (Month)" },
  { id: "pendingFee", label: "Pending Fees" },
];

function ReportStudentSummary({ data }) {
  const [locationId, setLocationId] = useState("ALL");
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");
  const [from, setFrom] = useState(startOfMonth(shiftMonths(todayISO(), -2)));
  const [to, setTo] = useState(endOfMonth(todayISO()));
  const months = monthsBetween(from, to);
  const locationStudents = data.students.filter((s) => locationId === "ALL" || s.locationId === locationId);
  const q = search.trim().toLowerCase();
  const searchedStudents = q
    ? locationStudents.filter((s) => s.name.toLowerCase().includes(q) || (s.jerseyName || "").toLowerCase().includes(q) || String(s.jerseyNo).toLowerCase().includes(q))
    : locationStudents;
  const students = statusFilter === "All" ? searchedStudents : searchedStudents.filter((s) => s.status === statusFilter);

  const exportExcel = () => {
    const headers = ["Player Name", "Jersey Name", "Jersey No.", "Batch", "Contact", "Player Status", ...months.flatMap((m) => [`${fmtMonth(m)} Sessions`, `${fmtMonth(m)} Fee Paid`])];
    const rows = students.map((s) => [
      s.name, s.jerseyName, s.jerseyNo, batchName(data, s.batchId), s.phone, s.status,
      ...months.flatMap((m) => [sessionsCountForStudentInMonth(data, s.id, monthKey(m)), feePaidForStudentInMonth(data, s.id, monthKey(m))]),
    ]);
    downloadXLSX("player-fee-attendance-report.xlsx", headers, rows);
  };

  return (
    <div>
      <div className="sa-report-filters">
        <Field label="Location">
          <select value={locationId} onChange={(e) => setLocationId(e.target.value)}>
            <option value="ALL">All Locations</option>
            {data.locations.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
          </select>
        </Field>
        <Field label="Search">
          <div className="sa-field-search">
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Name, jersey name, or jersey no." autoComplete="off" autoCorrect="off" autoCapitalize="off" spellCheck={false} />
            {search && <SearchClearButton onClear={() => setSearch("")} />}
          </div>
        </Field>
        <Field label="Status">
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option>All</option><option>Active</option><option>Inactive</option>
          </select>
        </Field>
        <Field label="From"><DateInput value={from} onChange={(e) => setFrom(e.target.value)} /></Field>
        <Field label="To"><DateInput value={to} onChange={(e) => setTo(e.target.value)} /></Field>
        <button className="sa-btn sa-btn-primary sa-btn-sm" onClick={exportExcel}><Download size={14} /> Export to Excel</button>
      </div>
      <div className="sa-table-wrap">
        <table className="sa-table sa-table-compact">
          <thead>
            <tr>
              <th rowSpan={2}>Player</th><th rowSpan={2}>Jersey Name</th><th rowSpan={2}>Jersey No.</th><th rowSpan={2}>Batch</th><th rowSpan={2}>Contact</th><th rowSpan={2}>Player Status</th>
              {months.map((m) => <th key={m} colSpan={2} className="sa-th-center">{fmtMonth(m)}</th>)}
            </tr>
            <tr>
              {months.map((m) => (
                <React.Fragment key={m}>
                  <th className="sa-th-sub">Sessions</th>
                  <th className="sa-th-sub">Fee Paid</th>
                </React.Fragment>
              ))}
            </tr>
          </thead>
          <tbody>
            {students.map((s) => (
              <tr key={s.id}>
                <td className="sa-td-strong">{s.name}</td>
                <td>{s.jerseyName || "\u2014"}</td>
                <td>#{s.jerseyNo}</td>
                <td>{batchName(data, s.batchId)}</td>
                <td>{s.phone}</td>
                <td><Pill tone={s.status === "Active" ? "teal" : "red"}>{s.status}</Pill></td>
                {months.map((m) => (
                  <React.Fragment key={m}>
                    <td className="sa-mono sa-th-center">{sessionsCountForStudentInMonth(data, s.id, monthKey(m))}</td>
                    <td className="sa-mono sa-th-center">{money(feePaidForStudentInMonth(data, s.id, monthKey(m)))}</td>
                  </React.Fragment>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function ReportAttendance({ data }) {
  const [locationId, setLocationId] = useState(data.locations[0]?.id || "");
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");
  const [from, setFrom] = useState(startOfMonth(todayISO()));
  const [to, setTo] = useState(endOfMonth(todayISO()));

  const sessDates = [...new Set(data.sessions.filter((s) => s.locationId === locationId && s.date >= from && s.date <= to).map((s) => s.date))].sort();
  const locationStudents = data.students.filter((s) => s.locationId === locationId);
  const q = search.trim().toLowerCase();
  const searchedStudents = q
    ? locationStudents.filter((s) => s.name.toLowerCase().includes(q) || (s.jerseyName || "").toLowerCase().includes(q) || String(s.jerseyNo).toLowerCase().includes(q))
    : locationStudents;
  const students = statusFilter === "All" ? searchedStudents : searchedStudents.filter((s) => s.status === statusFilter);

  const attendedOnDate = (studentId, date) => {
    const sessIds = data.sessions.filter((s) => s.locationId === locationId && s.date === date).map((s) => s.id);
    return data.attendance.some((a) => a.studentId === studentId && sessIds.includes(a.sessionId) && a.status === "P")
      ? "P"
      : data.attendance.some((a) => a.studentId === studentId && sessIds.includes(a.sessionId) && a.status === "A")
      ? "A"
      : "\u2013";
  };
  const dailyCount = (date) => {
    const sessIds = data.sessions.filter((s) => s.locationId === locationId && s.date === date).map((s) => s.id);
    return data.attendance.filter((a) => sessIds.includes(a.sessionId) && a.status === "P").length;
  };
  const totalForStudent = (studentId) => sessDates.filter((d) => attendedOnDate(studentId, d) === "P").length;

  const exportExcel = () => {
    const headers = ["Player Name", "Jersey Name", "Jersey No.", "Batch", "Contact", "Player Status", ...sessDates.map(fmtDateShort), "Total Present"];
    const rows = students.map((s) => [
      s.name, s.jerseyName, s.jerseyNo, batchName(data, s.batchId), s.phone, s.status,
      ...sessDates.map((d) => attendedOnDate(s.id, d)), totalForStudent(s.id),
    ]);
    downloadXLSX("attendance-report.xlsx", headers, rows);
  };

  return (
    <div>
      <div className="sa-report-filters">
        <Field label="Location">
          <select value={locationId} onChange={(e) => setLocationId(e.target.value)}>
            {data.locations.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
          </select>
        </Field>
        <Field label="Search">
          <div className="sa-field-search">
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Name, jersey name, or jersey no." autoComplete="off" autoCorrect="off" autoCapitalize="off" spellCheck={false} />
            {search && <SearchClearButton onClear={() => setSearch("")} />}
          </div>
        </Field>
        <Field label="Status">
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option>All</option><option>Active</option><option>Inactive</option>
          </select>
        </Field>
        <Field label="From"><DateInput value={from} onChange={(e) => setFrom(e.target.value)} /></Field>
        <Field label="To"><DateInput value={to} onChange={(e) => setTo(e.target.value)} /></Field>
        <button className="sa-btn sa-btn-primary sa-btn-sm" onClick={exportExcel}><Download size={14} /> Export to Excel</button>
      </div>

      {sessDates.length === 0 ? (
        <p className="sa-muted-text">No sessions scheduled for this location in the selected period.</p>
      ) : (
        <>
          <div className="sa-attendance-header-strip">
            {sessDates.map((d) => (
              <div key={d} className="sa-att-header-cell">
                <span>{fmtDateShort(d)}</span>
                <strong>{dailyCount(d)}</strong>
              </div>
            ))}
          </div>
          <div className="sa-table-wrap">
            <table className="sa-table sa-table-compact">
              <thead>
                <tr>
                  <th>Player</th><th>Jersey Name</th><th>Jersey No.</th><th>Batch</th><th>Contact</th><th>Player Status</th>
                  {sessDates.map((d) => <th key={d} className="sa-th-center">{fmtDateShort(d)}</th>)}
                  <th className="sa-th-center">Total</th>
                </tr>
              </thead>
              <tbody>
                {students.map((s) => (
                  <tr key={s.id}>
                    <td className="sa-td-strong">{s.name}</td>
                    <td>{s.jerseyName || "\u2014"}</td>
                    <td>#{s.jerseyNo}</td>
                    <td>{batchName(data, s.batchId)}</td>
                    <td>{s.phone}</td>
                    <td><Pill tone={s.status === "Active" ? "teal" : "red"}>{s.status}</Pill></td>
                    {sessDates.map((d) => {
                      const v = attendedOnDate(s.id, d);
                      return <td key={d} className={`sa-th-center ${v === "P" ? "sa-att-p" : v === "A" ? "sa-att-a" : ""}`}>{v}</td>;
                    })}
                    <td className="sa-mono sa-th-center">{totalForStudent(s.id)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}

function ReportFeeList({ data }) {
  const [locationId, setLocationId] = useState(data.locations[0]?.id || "");
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");
  const [month, setMonth] = useState(monthKey(todayISO()));

  const locationStudents = data.students.filter((s) => s.locationId === locationId);
  const q = search.trim().toLowerCase();
  const searchedStudents = q
    ? locationStudents.filter((s) => s.name.toLowerCase().includes(q) || (s.jerseyName || "").toLowerCase().includes(q) || String(s.jerseyNo).toLowerCase().includes(q))
    : locationStudents;
  const students = statusFilter === "All" ? searchedStudents : searchedStudents.filter((s) => s.status === statusFilter);
  const rowFor = (s) => {
    const monthPayments = data.payments.filter((p) => p.studentId === s.id && monthKey(p.date) === month);
    const coveringPayment = studentPayments(data, s.id).find((p) => p.endDate && monthKey(p.endDate) === month);
    const amountPaid = monthPayments.length > 0
      ? monthPayments.reduce((a, p) => a + Number(p.amount), 0)
      : Number(coveringPayment?.amount || 0);
    const last = monthPayments.sort((a, b) => (a.date < b.date ? 1 : -1))[0] || coveringPayment || latestPayment(data, s.id);
    const paid = studentFeeStatus(data, s) === "Paid";
    const dueAmount = paid ? 0 : studentExpectedFee(data, s);
    return { s, paid, amountPaid, receiptNo: last?.receiptNo || "\u2014", nextDue: last?.nextPaymentDate, dueAmount: Math.max(dueAmount, 0) };
  };
  const rows = students.map(rowFor);

  const exportExcel = () => {
    const headers = ["Player Name", "Jersey Name", "Jersey No.", "Contact", "Player Status", "Status", "Amount Paid", "Receipt No.", "Next Payment Date", "Due Amount"];
    const data_ = rows.map((r) => [r.s.name, r.s.jerseyName, r.s.jerseyNo, r.s.phone, r.s.status, r.paid ? "Paid" : "Unpaid", r.amountPaid, r.receiptNo, fmtDate(r.nextDue), r.dueAmount]);
    downloadXLSX("fee-list-report.xlsx", headers, data_);
  };

  return (
    <div>
      <div className="sa-report-filters">
        <Field label="Location">
          <select value={locationId} onChange={(e) => setLocationId(e.target.value)}>
            {data.locations.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
          </select>
        </Field>
        <Field label="Search">
          <div className="sa-field-search">
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Name, jersey name, or jersey no." autoComplete="off" autoCorrect="off" autoCapitalize="off" spellCheck={false} />
            {search && <SearchClearButton onClear={() => setSearch("")} />}
          </div>
        </Field>
        <Field label="Player Status">
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option>All</option><option>Active</option><option>Inactive</option>
          </select>
        </Field>
        <Field label="Month"><input type="month" value={month} onChange={(e) => setMonth(e.target.value)} /></Field>
        <button className="sa-btn sa-btn-primary sa-btn-sm" onClick={exportExcel}><Download size={14} /> Export to Excel</button>
      </div>
      <div className="sa-table-wrap">
        <table className="sa-table sa-table-compact">
          <thead><tr><th>Player</th><th>Jersey Name</th><th>Jersey No.</th><th>Contact</th><th>Player Status</th><th>Status</th><th>Amount Paid</th><th>Receipt No.</th><th>Next Due</th><th>Due Amount</th></tr></thead>
          <tbody>
            {rows.map(({ s, paid, amountPaid, receiptNo, nextDue, dueAmount }) => (
              <tr key={s.id} className={paid ? "sa-row-paid" : "sa-row-unpaid"}>
                <td className="sa-td-strong">{s.name}</td>
                <td>{s.jerseyName || "\u2014"}</td>
                <td>#{s.jerseyNo}</td>
                <td>{s.phone}</td>
                <td><Pill tone={s.status === "Active" ? "teal" : "red"}>{s.status}</Pill></td>
                <td><Pill tone={paid ? "teal" : "red"}>{paid ? "Paid" : "Unpaid"}</Pill></td>
                <td className="sa-mono">{money(amountPaid)}</td>
                <td className="sa-mono">{receiptNo}</td>
                <td>{fmtDate(nextDue)}</td>
                <td className="sa-mono">{money(dueAmount)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function ReportPendingFee({ data }) {
  const [locationId, setLocationId] = useState(data.locations[0]?.id || "");
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");
  const [asOf, setAsOf] = useState(todayISO());

  const locationStudents = data.students.filter((s) => s.locationId === locationId);
  const q = search.trim().toLowerCase();
  const searchedStudents = q
    ? locationStudents.filter((s) => s.name.toLowerCase().includes(q) || (s.jerseyName || "").toLowerCase().includes(q) || String(s.jerseyNo).toLowerCase().includes(q))
    : locationStudents;
  const students = statusFilter === "All" ? searchedStudents : searchedStudents.filter((s) => s.status === statusFilter);
  const rows = students
    .map((s) => {
      const last = latestPayment(data, s.id);
      const overdue = !last || !last.nextPaymentDate || last.nextPaymentDate <= asOf;
      const dueAmount = totalOverdueAmountFor(data, s, asOf);
      const sessionsAfterDue = last
        ? data.sessions.filter((se) => se.locationId === locationId && se.date >= last.nextPaymentDate && se.date <= asOf)
            .filter((se) => data.attendance.some((a) => a.sessionId === se.id && a.studentId === s.id && a.status === "P")).length
        : 0;
      return { s, overdue, last, dueAmount, sessionsAfterDue };
    })
    // A student with no fee record at all (r.last is null — never made a Fee payment) is always
    // included here regardless of recent attendance, since there's no due date yet to measure
    // "pending since" against — they just owe their first cycle. Everyone else still needs the
    // usual isPendingForFees recency check.
    .filter((r) => r.overdue && (r.last === null || isPendingForFees(data, r.s, asOf)))
    // ADDITIONAL CHECK: an Inactive student only stays on this list if they've attended at least
    // one session on/after their own due date (sessionsAfterDue >= 1) — same "attended after due
    // date" bar Active students already clear via computeOutstanding's sessionsAfterDue check.
    // Active students are unaffected by this line.
    .filter((r) => r.s.status === "Active" || r.sessionsAfterDue >= 1)
    // ADDITIONAL CHECK: any student who already has a payment record (r.last !== null) — Active or
    // Inactive — must also show at least 1 session attended on/after their due date to stay on the
    // list, matching what "No. of sessions(pending payment)" = 0 on the exported row means: they
    // haven't actually shown up since becoming due. Dashboard's computeOutstanding already enforces
    // this same sessionsAfterDue >= 1 bar for students with a payment record, so this brings the
    // report's row list in line with the dashboard total. Students with no payment record at all
    // (r.last === null) are untouched by this line — they keep the never-paid exception above.
    .filter((r) => r.last === null || r.sessionsAfterDue >= 1);

  const exportExcel = () => {
    const headers = ["Player Name", "Jersey Name", "Jersey No.", "Contact", "Player Status", "Status", "Amount Paid", "Receipt No.", "Next Payment Date", "Due Amount", "No. of sessions(pending payment)"];
    const data_ = rows.map((r) => [r.s.name, r.s.jerseyName, r.s.jerseyNo, r.s.phone, r.s.status, "Unpaid", r.last ? r.last.amount : 0, r.last?.receiptNo || "\u2014", fmtDate(r.last?.nextPaymentDate), r.dueAmount, r.sessionsAfterDue]);
    downloadXLSX(`pending-fees-${asOf}.xlsx`, headers, data_);
  };

  return (
    <div>
      <div className="sa-report-filters">
        <Field label="Location">
          <select value={locationId} onChange={(e) => setLocationId(e.target.value)}>
            {data.locations.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
          </select>
        </Field>
        <Field label="Search">
          <div className="sa-field-search">
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Name, jersey name, or jersey no." autoComplete="off" autoCorrect="off" autoCapitalize="off" spellCheck={false} />
            {search && <SearchClearButton onClear={() => setSearch("")} />}
          </div>
        </Field>
        <Field label="Player Status">
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option>All</option><option>Active</option><option>Inactive</option>
          </select>
        </Field>
        <Field label="As Of Date"><DateInput value={asOf} onChange={(e) => setAsOf(e.target.value)} /></Field>
        <button className="sa-btn sa-btn-primary sa-btn-sm" onClick={exportExcel}><Download size={14} /> Export to Excel</button>
      </div>
      {rows.length === 0 ? (
        <p className="sa-muted-text">No pending fees for this location as of {fmtDate(asOf)}.</p>
      ) : (
        <div className="sa-table-wrap">
          <table className="sa-table sa-table-compact">
            <thead><tr><th>Player</th><th>Jersey Name</th><th>Jersey No.</th><th>Contact</th><th>Player Status</th><th>Due Amount</th><th>Receipt No.</th><th>Next Due</th><th>No. of sessions(pending payment)</th></tr></thead>
            <tbody>
              {rows.map(({ s, last, dueAmount, sessionsAfterDue }) => (
                <tr key={s.id} className="sa-row-unpaid">
                  <td className="sa-td-strong">{s.name}</td>
                  <td>{s.jerseyName || "\u2014"}</td>
                  <td>#{s.jerseyNo}</td>
                  <td>{s.phone}</td>
                  <td><Pill tone={s.status === "Active" ? "teal" : "red"}>{s.status}</Pill></td>
                  <td className="sa-mono">{money(dueAmount)}</td>
                  <td className="sa-mono">{last?.receiptNo || "\u2014"}</td>
                  <td>{fmtDate(last?.nextPaymentDate)}</td>
                  <td className="sa-mono">{sessionsAfterDue}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

