const ADMIN_ROLES = ["super_admin", "location_admin"];
const roleLabel = (role) => (role === "super_admin" ? "Super Admin" : "Location Admin");

function AdminForm({ data, initial, submitting, onCancel, onSave }) {
  const [form, setForm] = useState(initial);
  const toggleLocation = (id) => {
    setForm((f) => ({
      ...f,
      locationIds: f.locationIds.includes(id) ? f.locationIds.filter((x) => x !== id) : [...f.locationIds, id],
    }));
  };
  const isEdit = Boolean(initial.id);
  const canSubmit = form.name.trim() && (isEdit || form.email.trim()) && (form.role === "super_admin" || form.locationIds.length > 0);
  return (
    <div className="sa-form">
      <div className="sa-form-row">
        <Field label="Full Name">
          <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Admin name" />
        </Field>
        <Field label="Email (Login ID)">
          <input
            type="email"
            value={isEdit ? "Set at invite time — not editable" : form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value })}
            placeholder="name@cffa.ae"
            disabled={isEdit}
          />
        </Field>
      </div>
      <Field label="Role">
        <select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>
          {ADMIN_ROLES.map((r) => <option key={r} value={r}>{roleLabel(r)}</option>)}
        </select>
      </Field>
      {form.role === "location_admin" && (
        <Field label="Assigned Locations">
          <div className="sa-checkbox-group">
            {data.locations.map((l) => (
              <label key={l.id} className="sa-checkbox">
                <input type="checkbox" checked={form.locationIds.includes(l.id)} onChange={() => toggleLocation(l.id)} />
                {l.name}
              </label>
            ))}
          </div>
        </Field>
      )}
      {form.role === "super_admin" && (
        <p className="sa-muted-text">Super Admins can see and manage every location automatically.</p>
      )}
      <div className="sa-form-actions">
        <button className="sa-btn sa-btn-ghost" disabled={submitting} onClick={onCancel}>Cancel</button>
        <button className="sa-btn sa-btn-primary" disabled={!canSubmit || submitting} onClick={() => { if (canSubmit && !submitting) onSave(form); }}>
          {submitting ? "Saving…" : (initial.status === "Invited" || !initial.id ? "Send Invite" : "Save Changes")}
        </button>
      </div>
    </div>
  );
}

function ManageAdminsPage({ currentRole }) {
  const [locations, setLocations] = useState([]);
  const [admins, setAdmins] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [modal, setModal] = useState(null);
  const [confirmRevoke, setConfirmRevoke] = useState(null);
  const [saveError, setSaveError] = useState(null);
  const [saving, setSaving] = useState(false);
  const savingRef = useRef(false);
  const blank = { name: "", email: "", role: "location_admin", locationIds: [], status: "Invited" };

  const refetch = useCallback(async () => {
    const [locRes, profRes, accessRes] = await Promise.all([
      supabase.from("locations").select("*").order("name"),
      supabase.from("admin_profiles").select("*"),
      supabase.from("admin_location_access").select("*"),
    ]);
    setLocations((locRes.data || []).map((l) => ({ id: l.id, name: l.name })));
    const accessMap = {};
    (accessRes.data || []).forEach((a) => { (accessMap[a.user_id] ||= []).push(a.location_id); });
    setAdmins((profRes.data || []).map((p) => ({
      id: p.id, name: p.name, role: p.role, status: p.status,
      locationIds: accessMap[p.id] || [],
    })));
    setLoaded(true);
  }, []);

  useEffect(() => {
    if (currentRole === "super_admin") refetch();
  }, [currentRole, refetch]);

  if (currentRole !== "super_admin") {
    return (
      <EmptyState
        icon={ShieldOff}
        title="Access restricted"
        message="This page is only available to Super Admins. Switch to Super Admin in the sidebar to manage admin access."
      />
    );
  }

  if (!loaded) return null;

  const openInvite = () => setModal({ mode: "add" });
  const openEdit = (a) => setModal({ mode: "edit", id: a.id, initial: { ...a, email: "" } });

  const save = async (form) => {
    if (savingRef.current) return;
    savingRef.current = true;
    setSaving(true);
    try {
      if (modal.mode === "add") {
        const { data: result, error } = await supabase.functions.invoke("invite-admin", {
          body: { email: form.email, name: form.name, role: form.role, locationIds: form.locationIds },
        });
        if (error) {
          let message = error.message;
          if (error.context) {
            try {
              const body = await error.context.json();
              if (body?.error) message = body.error;
            } catch {
              // response body wasn't JSON — fall back to the generic message
            }
          }
          setSaveError(message);
          return;
        }
        if (result?.error) { setSaveError(result.error); return; }
        setSaveError(null);
        await refetch();
        setModal(null);
        return;
      }
      const { error } = await supabase
        .from("admin_profiles")
        .update({ name: form.name, role: form.role })
        .eq("id", modal.id);
      if (error) { setSaveError(error.message); return; }
      await supabase.from("admin_location_access").delete().eq("user_id", modal.id);
      if (form.role !== "super_admin" && form.locationIds.length > 0) {
        const { error: accessErr } = await supabase.from("admin_location_access").insert(
          form.locationIds.map((location_id) => ({ user_id: modal.id, location_id }))
        );
        if (accessErr) { setSaveError(accessErr.message); return; }
      }
      setSaveError(null);
      await refetch();
      setModal(null);
    } finally {
      savingRef.current = false;
      setSaving(false);
    }
  };

  const revoke = async (id) => {
    await supabase.from("admin_profiles").update({ status: "Revoked" }).eq("id", id);
    await refetch();
    setConfirmRevoke(null);
  };

  return (
    <div className="sa-page">
      <div className="sa-storage-warning" style={{ background: "#EFF6FF", color: "#1D4ED8", borderColor: "#BFDBFE" }}>
        <ShieldCheck size={14} /> "Invite Admin" needs the Edge Function from step 4.6 (creating a login requires the service role key, which never runs in the browser). Editing role/locations for existing admins already writes to Supabase directly. Email addresses aren't shown here yet since that also needs the Edge Function to read them from Supabase Auth.
      </div>

      <div className="sa-page-actions">
        <div />
        <button className="sa-btn sa-btn-primary" onClick={openInvite}><Plus size={16} /> Invite Admin</button>
      </div>

      {admins.length === 0 ? (
        <EmptyState icon={ShieldCheck} title="No admins yet" message="Invite your first admin to get started." />
      ) : (
        <div className="sa-table-wrap">
          <table className="sa-table sa-table-compact">
            <thead>
              <tr><th>Name</th><th>Role</th><th>Assigned Locations</th><th>Status</th><th></th></tr>
            </thead>
            <tbody>
              {admins.map((a) => (
                <tr key={a.id}>
                  <td className="sa-td-strong">{a.name}</td>
                  <td><Pill tone={a.role === "super_admin" ? "amber" : "neutral"}>{roleLabel(a.role)}</Pill></td>
                  <td>
                    {a.role === "super_admin"
                      ? "All Locations"
                      : a.locationIds.map((lid) => locations.find((l) => l.id === lid)?.name).filter(Boolean).join(", ") || "\u2014"}
                  </td>
                  <td><Pill tone={a.status === "Active" ? "teal" : "amber"}>{a.status}</Pill></td>
                  <td className="sa-td-actions">
                    <button className="sa-icon-btn" onClick={() => openEdit(a)}><Pencil size={14} /></button>
                    <button className="sa-icon-btn" onClick={() => setConfirmRevoke(a.id)}><Trash2 size={14} /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {modal && (
        <Modal title={modal.mode === "add" ? "Invite Admin" : "Edit Admin"} onClose={() => setModal(null)}>
          {saveError && <div className="sa-login-error"><AlertCircle size={14} /> {saveError}</div>}
          <AdminForm data={{ locations }} initial={modal.mode === "add" ? blank : modal.initial} submitting={saving} onCancel={() => setModal(null)} onSave={save} />
        </Modal>
      )}

      {confirmRevoke && (
        <ConfirmDialog
          message="Revoke this admin's access? They will no longer be able to log in or view any location's data."
          onCancel={() => setConfirmRevoke(null)}
          onConfirm={() => revoke(confirmRevoke)}
        />
      )}
    </div>
  );
}

