export default function App() {
  const [data, setData] = useState(null);
  const [dataError, setDataError] = useState(null);
  const [view, setView] = useState("dashboard");
  const [collapsed, setCollapsed] = useState(false);
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const [locationId, setLocationId] = useState("");
  const [dashLocationId, setDashLocationId] = useState("ALL");

  const [session, setSession] = useState(undefined); // undefined = still checking, null = signed out
  const [adminProfile, setAdminProfile] = useState(null);
  const [profileLoaded, setProfileLoaded] = useState(false);
  const [profileError, setProfileError] = useState(null);
  // Invite/recovery links redirect back here with #access_token=...&type=invite (or recovery)
  // in the URL hash — detect that up front so we can prompt for a password before showing the app.
  const [needsPasswordSetup, setNeedsPasswordSetup] = useState(
    () => window.location.hash.includes("type=invite") || window.location.hash.includes("type=recovery")
  );

  const refetchData = useCallback(async () => {
    try {
      const fresh = await loadAllData();
      setData(fresh);
      setDataError(null);
    } catch (e) {
      setDataError(e.message || "Failed to load data");
    }
  }, []);

  useEffect(() => {
    // Number inputs change value on scroll when focused, which is easy to trigger by
    // accident while scrolling the page — blur before the browser applies the scroll delta.
    const onWheel = (e) => {
      if (document.activeElement?.tagName === "INPUT" && document.activeElement.type === "number") {
        document.activeElement.blur();
      }
    };
    document.addEventListener("wheel", onWheel, { passive: true });
    return () => document.removeEventListener("wheel", onWheel);
  }, []);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => setSession(session));
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => listener.subscription.unsubscribe();
  }, []);

  const profileFetchedForUserId = useRef(null);

  useEffect(() => {
    if (session === undefined) return;
    if (!session) {
      profileFetchedForUserId.current = null;
      setAdminProfile(null);
      setProfileLoaded(true);
      return;
    }
    // Supabase re-emits auth state (e.g. token refresh) whenever the tab regains
    // focus/visibility. That's not a new sign-in, so skip re-fetching/reloading
    // for the same user — otherwise every tab switch flashes the loading screen,
    // unmounts the app (closing any open modal), and refetches all data.
    if (profileFetchedForUserId.current === session.user.id) return;
    profileFetchedForUserId.current = session.user.id;
    setProfileLoaded(false);
    setProfileError(null);
    let cancelled = false;
    (async () => {
      // admin_profiles and admin_location_access both reference auth.users
      // independently (no direct FK between the two), so PostgREST can't
      // embed one inside the other — fetch them as two separate queries.
      const { data: profile, error: profileErr } = await supabase
        .from("admin_profiles")
        .select("*")
        .eq("id", session.user.id)
        .single();
      if (cancelled) return;
      if (profileErr || !profile) {
        setAdminProfile(null);
        setProfileError(profileErr?.message || "No admin profile found");
        setProfileLoaded(true);
        return;
      }
      const { data: access, error: accessErr } = await supabase
        .from("admin_location_access")
        .select("location_id")
        .eq("user_id", session.user.id);
      if (cancelled) return;
      if (accessErr) setProfileError(accessErr.message);
      setAdminProfile({ ...profile, admin_location_access: access || [] });
      setProfileLoaded(true);
    })();
    return () => { cancelled = true; };
  }, [session]);

  useEffect(() => {
    if (adminProfile) refetchData();
  }, [adminProfile, refetchData]);

  const currentRole = adminProfile?.role || "location_admin";

  useEffect(() => {
    if (!data) return;
    const allowedIds = data.locations.map((l) => l.id);
    if (allowedIds.length > 0 && !allowedIds.includes(locationId)) {
      setLocationId(allowedIds[0]);
    }
  }, [data, locationId]);

  async function handleSignOut() {
    await supabase.auth.signOut();
  }

  if (session === undefined || !profileLoaded) {
    return (
      <div className="sa-root sa-root-loading">
        <style>{STYLES}</style>
        <div className="sa-loading">
          <div className="sa-loading-mark">SA</div>
          <span>{"Loading\u2026"}</span>
        </div>
      </div>
    );
  }

  if (!session) {
    return <LoginPage />;
  }

  if (needsPasswordSetup) {
    return (
      <PasswordSetupPage
        onDone={async () => {
          await supabase.from("admin_profiles").update({ status: "Active" }).eq("id", session.user.id);
          setAdminProfile((prev) => (prev ? { ...prev, status: "Active" } : prev));
          window.history.replaceState(null, "", window.location.pathname);
          setNeedsPasswordSetup(false);
        }}
      />
    );
  }

  if (!adminProfile) {
    return (
      <div className="sa-root sa-root-loading">
        <style>{STYLES}</style>
        <div className="sa-loading">
          <div className="sa-loading-mark">SA</div>
          <span>No admin profile found for this account. Contact a super admin.</span>
          {profileError && <span className="sa-login-error"><AlertCircle size={14} /> {profileError}</span>}
          <button className="sa-btn sa-btn-ghost" onClick={handleSignOut}>Sign Out</button>
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="sa-root sa-root-loading">
        <style>{STYLES}</style>
        <div className="sa-loading">
          <div className="sa-loading-mark">SA</div>
          <span>Loading academy data…</span>
          {dataError && <span className="sa-login-error"><AlertCircle size={14} /> {dataError}</span>}
        </div>
      </div>
    );
  }

  return (
    <div className="sa-root">
      <style>{STYLES}</style>
      <Sidebar
        view={view} setView={setView} collapsed={collapsed} setCollapsed={setCollapsed}
        currentRole={currentRole} adminName={adminProfile.name} onSignOut={handleSignOut}
        mobileOpen={mobileNavOpen} onCloseMobile={() => setMobileNavOpen(false)}
      />
      <div className="sa-main">
        <Topbar
          view={view} data={data} locationId={locationId} setLocationId={setLocationId}
          onOpenMobileNav={() => setMobileNavOpen(true)}
        />
        <div className="sa-content">
          {dataError && (
            <div className="sa-storage-warning"><AlertCircle size={14} /> {dataError}</div>
          )}
          {view === "dashboard" && <DashboardPage data={data} dashLocationId={dashLocationId} setDashLocationId={setDashLocationId} />}
          {view === "locations" && <LocationsPage data={data} refetchData={refetchData} />}
          {view === "paymentPlans" && <PaymentPlansPage data={data} refetchData={refetchData} locationId={locationId} />}
          {view === "batches" && <BatchesPage data={data} refetchData={refetchData} locationId={locationId} />}
          {view === "students" && <StudentsPage data={data} refetchData={refetchData} locationId={locationId} />}
          {view === "attendance" && <AttendancePage data={data} refetchData={refetchData} locationId={locationId} />}
          {view === "coaches" && <CoachesPage data={data} refetchData={refetchData} locationId={locationId} />}
          {view === "schedules" && <SchedulesPage data={data} refetchData={refetchData} locationId={locationId} />}
          {view === "feeUpdate" && <FeeUpdatePage data={data} refetchData={refetchData} locationId={locationId} />}
          {view === "reports" && <ReportsPage data={data} />}
          {view === "manageAdmins" && <ManageAdminsPage currentRole={currentRole} />}
        </div>
      </div>
    </div>
  );
}

/* ============================== STYLES ============================== */

const STYLES = `
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@500;600;700&display=swap');

:root {
  --navy: #0F1B2D;
  --navy-light: #16273D;
  --navy-lighter: #1E3350;
  --amber: #FFB020;
  --teal: #14B8A6;
  --red: #EF4444;
  --bg: #F4F5F2;
  --card: #FFFFFF;
  --ink: #101826;
  --muted: #6B7280;
  --border: #E5E7EB;
}

.sa-root * { box-sizing: border-box; }
.sa-root {
  display: flex;
  min-height: 100vh;
  background: var(--bg);
  font-family: 'Inter', sans-serif;
  color: var(--ink);
}
.sa-root-loading { align-items: center; justify-content: center; }
.sa-loading { display: flex; flex-direction: column; align-items: center; gap: 14px; color: var(--muted); }
.sa-loading-mark {
  width: 56px; height: 56px; border-radius: 12px; background: var(--navy); color: var(--amber);
  display: flex; align-items: center; justify-content: center; font-family: 'Oswald', sans-serif;
  font-weight: 700; font-size: 20px; letter-spacing: 0.5px;
}

/* ---------- Sidebar ---------- */
.sa-sidebar {
  width: 232px; background: var(--navy); color: #fff; display: flex; flex-direction: column;
  flex-shrink: 0; transition: width 0.2s ease; position: relative;
}
.sa-sidebar-collapsed { width: 72px; }
.sa-sidebar-brand { display: flex; align-items: center; gap: 10px; padding: 20px 16px; position: relative; }
.sa-brand-logo {
  height: 34px; width: auto; max-width: 44px; object-fit: contain; flex-shrink: 0;
}
.sa-brand-text { line-height: 1.2; overflow: hidden; white-space: nowrap; }
.sa-brand-title { font-family: 'Oswald', sans-serif; font-weight: 600; font-size: 15px; letter-spacing: 1.5px; }
.sa-brand-sub { font-size: 11px; color: #8CA0BC; }
.sa-collapse-btn { margin-left: auto; color: #8CA0BC; }
.sa-nav { display: flex; flex-direction: column; gap: 2px; padding: 8px 12px; flex: 1; }
.sa-nav-item {
  display: flex; align-items: center; gap: 12px; padding: 10px 12px; border: none; background: none;
  color: #B7C4D6; font-family: 'Inter', sans-serif; font-size: 13.5px; font-weight: 500; border-radius: 8px;
  cursor: pointer; text-align: left; position: relative; white-space: nowrap; overflow: hidden;
}
.sa-nav-item:hover { background: var(--navy-light); color: #fff; }
.sa-nav-item-active { background: var(--navy-lighter); color: #fff; }
.sa-nav-indicator { position: absolute; left: -12px; top: 8px; bottom: 8px; width: 3px; background: var(--amber); border-radius: 0 3px 3px 0; }
.sa-sidebar-footer { padding: 14px 18px 20px; font-size: 10.5px; color: #62759A; }
.sa-sidebar-footer-line { height: 1px; background: var(--navy-light); margin-bottom: 10px; }
.sa-signed-in-as { margin-bottom: 10px; }
.sa-signed-in-name { color: #fff; font-weight: 600; font-size: 12.5px; }
.sa-signed-in-role { color: #8CA0BC; font-size: 10.5px; margin-top: 2px; }
.sa-signout-btn { color: #B7C4D6 !important; border-color: var(--navy-light) !important; width: 100%; justify-content: center; }
.sa-signout-btn:hover { background: var(--navy-light) !important; }
.sa-mobile-backdrop { display: none; }
.sa-hamburger-btn { display: none !important; }

/* ---------- Login ---------- */
.sa-login-root {
  display: flex; align-items: center; justify-content: center; min-height: 100vh;
  background: var(--navy); font-family: 'Inter', sans-serif;
}
.sa-login-card {
  background: var(--card); border-radius: 14px; padding: 36px 34px; width: 340px;
  display: flex; flex-direction: column; gap: 14px; box-shadow: 0 20px 50px rgba(0,0,0,0.3);
}
.sa-login-logo { height: 40px; width: auto; max-width: 60px; object-fit: contain; margin: 0 auto 6px; }
.sa-login-card h2 {
  font-family: 'Oswald', sans-serif; font-size: 18px; font-weight: 600; text-align: center;
  color: var(--ink); margin: 0 0 8px;
}
.sa-login-error {
  display: flex; align-items: center; gap: 8px; background: #FEF2F2; color: var(--red);
  border: 1px solid #FECACA; padding: 8px 12px; border-radius: 8px; font-size: 12.5px;
}
.sa-login-submit { justify-content: center; margin-top: 4px; }

/* ---------- Topbar / Main ---------- */
.sa-main { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.sa-topbar {
  display: flex; align-items: center; justify-content: space-between; padding: 14px 28px;
  background: var(--card); border-bottom: 1px solid var(--border);
}
.sa-topbar-left { display: flex; align-items: center; gap: 12px; }
.sa-topbar-eyebrow { font-size: 14px; font-weight: 800; letter-spacing: 1px; text-transform: uppercase; color: var(--amber); margin-bottom: 2px; }
.sa-topbar-title { font-family: 'Oswald', sans-serif; font-size: 19px; font-weight: 600; letter-spacing: 0.3px; }
.sa-location-select {
  display: flex; align-items: center; gap: 8px; background: var(--bg); border: 1px solid var(--border);
  border-radius: 8px; padding: 6px 10px; color: var(--navy);
}
.sa-location-select select { border: none; background: none; font-family: 'Inter'; font-size: 13px; font-weight: 600; color: var(--ink); outline: none; }
.sa-content { padding: 20px 28px 36px; flex: 1; overflow-y: auto; }
.sa-storage-warning {
  display: flex; align-items: center; gap: 8px; background: #FFF7ED; color: #C2410C; border: 1px solid #FED7AA;
  padding: 10px 14px; border-radius: 8px; font-size: 13px; margin-bottom: 16px;
}
.sa-page { display: flex; flex-direction: column; gap: 14px; }

/* ---------- Scoreboard ---------- */
.sa-scoreboard { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; }
.sa-scorecard {
  background: var(--navy); border-radius: 12px; padding: 13px 16px; color: #fff; position: relative;
  overflow: hidden;
}
.sa-scorecard::after {
  content: ""; position: absolute; right: -20px; top: -20px; width: 90px; height: 90px; border-radius: 50%;
  background: rgba(255,176,32,0.08);
}
.sa-scorecard-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; }
.sa-scorecard-label { font-size: 11px; text-transform: uppercase; letter-spacing: 1.3px; color: #91A3BE; font-weight: 600; }
.sa-scorecard-value { font-family: 'JetBrains Mono', monospace; font-weight: 700; font-size: 24px; line-height: 1; }
.sa-scorecard-sub { margin-top: 5px; font-size: 11.5px; color: #8CA0BC; }

/* ---------- Cards / Grids ---------- */
.sa-dash-grid { display: grid; grid-template-columns: 1fr; gap: 16px; }
.sa-dash-grid > .sa-card { min-width: 0; }
.sa-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 20px; }
.sa-card-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.sa-card-header h3 { font-family: 'Oswald', sans-serif; font-size: 15px; font-weight: 600; letter-spacing: 0.3px; }
.sa-inline-select { border: 1px solid var(--border); border-radius: 6px; padding: 4px 7px; font-size: 12px; font-family: 'Inter'; background: var(--bg); }

.sa-week-strip { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px; overflow-x: auto; padding-bottom: 4px; }
.sa-week-col { background: var(--bg); border-radius: 8px; padding: 6px 4px; min-height: 120px; }
.sa-week-col-today { background: #FFF4E0; border: 1px solid #FFD98A; }
.sa-week-col-head { display: flex; flex-direction: column; align-items: center; margin-bottom: 6px; font-size: 11px; color: var(--muted); }
.sa-week-col-date { font-family: 'Oswald', sans-serif; font-size: 15px; color: var(--ink); font-weight: 600; }
.sa-week-empty { text-align: center; font-size: 11px; color: #C4CAD3; margin-top: 10px; }
.sa-week-chip { background: var(--card); border: 1px solid var(--border); border-radius: 6px; padding: 4px 4px; font-size: 10.5px; margin-bottom: 4px; display: flex; flex-direction: column; gap: 1px; }
.sa-week-chip-time { font-family: 'JetBrains Mono', monospace; font-weight: 700; color: var(--navy); white-space: nowrap; font-size: 9.5px; }
.sa-week-chip-batch { font-weight: 700; }
.sa-week-chip-loc { color: #fff; font-weight: 700; background: var(--navy); border-radius: 4px; padding: 1px 5px; display: inline-block; width: fit-content; }

.sa-card-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(270px, 1fr)); gap: 16px; }
.sa-loc-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 18px; display: flex; flex-direction: column; gap: 6px; }
.sa-loc-card-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px; }
.sa-loc-icon { width: 34px; height: 34px; border-radius: 8px; background: #FFF4E0; color: var(--amber); display: flex; align-items: center; justify-content: center; }
.sa-loc-card-actions { display: flex; gap: 4px; }
.sa-loc-card h3 { font-family: 'Oswald', sans-serif; font-size: 16px; font-weight: 600; }
.sa-loc-address { color: var(--muted); font-size: 12.5px; }
.sa-loc-meta { display: flex; flex-wrap: wrap; gap: 10px; font-size: 12px; color: var(--muted); align-items: center; }
.sa-loc-meta span { display: flex; align-items: center; gap: 4px; }
.sa-loc-stats { display: flex; gap: 12px; font-size: 12px; color: var(--navy); font-weight: 600; margin-top: 4px; }
.sa-dot { color: var(--border); }

/* ---------- Buttons ---------- */
.sa-btn {
  display: inline-flex; align-items: center; gap: 6px; border: none; border-radius: 8px; padding: 10px 16px;
  font-family: 'Inter'; font-size: 13.5px; font-weight: 600; cursor: pointer; transition: all .15s ease;
}
.sa-btn-primary { background: var(--navy); color: #fff; }
.sa-btn-primary:hover { background: var(--navy-lighter); }
.sa-btn-ghost { background: transparent; color: var(--navy); border: 1px solid var(--border); }
.sa-btn-ghost:hover { background: var(--bg); }
.sa-btn-danger { background: var(--red); color: #fff; }
.sa-btn-sm { padding: 6px 12px; font-size: 12.5px; }
.sa-icon-btn {
  border: none; background: transparent; color: var(--muted); width: 30px; height: 30px; border-radius: 7px;
  display: inline-flex; align-items: center; justify-content: center; cursor: pointer;
}
.sa-icon-btn:hover { background: var(--bg); color: var(--ink); }
.sa-icon-btn-placeholder { display: inline-block; width: 30px; height: 30px; flex-shrink: 0; }

.sa-page-actions { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.sa-search-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; flex: 1 1 auto; min-width: 0; }
.sa-search-box {
  display: flex; align-items: center; gap: 7px; background: var(--card); border: 1px solid var(--border);
  border-radius: 8px; padding: 6px 10px; min-width: 220px; color: var(--muted);
}
.sa-search-box input { border: none; outline: none; font-family: 'Inter'; font-size: 13px; width: 100%; color: var(--ink); }
.sa-search-clear-btn {
  display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px;
  border: none; background: transparent; padding: 0; color: var(--muted); cursor: pointer; border-radius: 4px; flex-shrink: 0;
}
.sa-search-clear-btn:hover { color: var(--ink); background: var(--bg); }
.sa-field-search { position: relative; display: flex; }
.sa-field-search input { flex: 1; padding-right: 30px; }
.sa-field-search .sa-search-clear-btn { position: absolute; right: 4px; top: 50%; transform: translateY(-50%); }

/* ---------- Table ---------- */
.sa-table-wrap { overflow-x: auto; border: 1px solid var(--border); border-radius: 10px; }
.sa-table { width: 100%; border-collapse: collapse; background: var(--card); font-size: 13px; }
.sa-table th {
  text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.6px; color: var(--muted);
  padding: 11px 14px; border-bottom: 1px solid var(--border); background: var(--bg); font-weight: 600; white-space: nowrap;
}
.sa-table td { padding: 11px 14px; border-bottom: 1px solid #F0F1EE; vertical-align: middle; white-space: nowrap; }
.sa-table tbody tr:last-child td { border-bottom: none; }
.sa-td-strong { font-weight: 600; }
.sa-mono { font-family: 'JetBrains Mono', monospace; font-size: 12.5px; }
.sa-td-actions { display: flex; gap: 2px; }
.sa-row-clickable { cursor: pointer; }
.sa-row-clickable:hover { background: var(--bg); }
th.sa-th-center, td.sa-th-center { text-align: center; }
.sa-th-sub { text-align: center; font-size: 10px; }
.sa-table-compact th, .sa-table-compact td { padding: 8px 10px; font-size: 12px; }
.sa-row-paid { background: #F0FDF9; }
.sa-row-unpaid { background: #FEF2F2; }
.sa-att-p { color: var(--teal); font-weight: 700; }
.sa-att-a { color: var(--red); font-weight: 700; }

/* ---------- Pills / Badges ---------- */
.sa-pill { display: inline-flex; align-items: center; padding: 3px 9px; border-radius: 20px; font-size: 11px; font-weight: 700; margin-left: 6px; text-transform: uppercase; letter-spacing: 0.4px; }
.sa-pill-teal { background: #CCFBF1; color: #0F766E; }
.sa-pill-red { background: #FEE2E2; color: #B91C1C; }
.sa-pill-amber { background: #FEF3C7; color: #92400E; }
.sa-pill-neutral { background: #EEF0F3; color: #4B5563; }
.sa-jersey {
  border-radius: 8px; background: var(--navy); color: var(--amber); display: flex; align-items: center;
  justify-content: center; font-family: 'JetBrains Mono', monospace; font-weight: 700; flex-shrink: 0;
}

/* ---------- Modal ---------- */
.sa-modal-overlay {
  position: fixed; inset: 0; background: rgba(15,27,45,0.55); display: flex; align-items: center; justify-content: center;
  z-index: 50; padding: 20px;
}
.sa-modal { background: var(--card); border-radius: 14px; width: 480px; max-width: 100%; max-height: 88vh; display: flex; flex-direction: column; overflow: hidden; }
.sa-modal-wide { width: 680px; }
.sa-modal-confirm { width: 380px; }
.sa-modal-header { display: flex; align-items: center; justify-content: space-between; padding: 18px 22px; border-bottom: 1px solid var(--border); }
.sa-modal-header h3 { font-family: 'Oswald', sans-serif; font-size: 17px; font-weight: 600; }
.sa-modal-body { padding: 20px 22px; overflow-y: auto; }

/* ---------- Forms ---------- */
.sa-form { display: flex; flex-direction: column; gap: 14px; }
.sa-form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.sa-field { display: flex; flex-direction: column; gap: 6px; font-size: 12.5px; font-weight: 600; color: var(--navy); }
.sa-field-required { color: #DC2626; }
.sa-field input, .sa-field select, .sa-field textarea {
  border: 1px solid var(--border); border-radius: 8px; padding: 9px 11px; font-family: 'Inter'; font-size: 13.5px;
  font-weight: 400; color: var(--ink); outline: none;
}
.sa-field input[type="number"] { -moz-appearance: textfield; }
.sa-field input[type="number"]::-webkit-outer-spin-button,
.sa-field input[type="number"]::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.sa-field input:focus, .sa-field select:focus { border-color: var(--amber); box-shadow: 0 0 0 3px rgba(255,176,32,0.15); }
.sa-field input[readonly] { background: var(--bg); color: var(--muted); cursor: not-allowed; }
.sa-field input[readonly]:focus { border-color: var(--border); box-shadow: none; }
.sa-date-input { position: relative; cursor: pointer; }
.sa-date-input input[type="date"] { width: 100%; cursor: pointer; color: transparent; }
.sa-date-input input[type="date"]::-webkit-datetime-edit,
.sa-date-input input[type="date"]::-webkit-datetime-edit-fields-wrapper,
.sa-date-input input[type="date"]::-webkit-datetime-edit-text,
.sa-date-input input[type="date"]::-webkit-datetime-edit-month-field,
.sa-date-input input[type="date"]::-webkit-datetime-edit-day-field,
.sa-date-input input[type="date"]::-webkit-datetime-edit-year-field {
  color: transparent;
  -webkit-text-fill-color: transparent;
  background: transparent;
}
.sa-date-input input[type="date"]::-webkit-datetime-edit-month-field:focus,
.sa-date-input input[type="date"]::-webkit-datetime-edit-day-field:focus,
.sa-date-input input[type="date"]::-webkit-datetime-edit-year-field:focus {
  background-color: transparent;
}
.sa-date-display {
  position: absolute; inset: 0; display: flex; align-items: center;
  pointer-events: none; font-family: 'Inter'; font-size: 13.5px; font-weight: 400; color: var(--ink);
  padding: 9px 11px;
}
.sa-inline-select.sa-date-input { display: inline-block; }
.sa-inline-select.sa-date-input .sa-date-display { padding: 4px 7px; font-size: 12px; }
.sa-inline-select.sa-att-date .sa-date-display { font-size: 13px; font-weight: 700; color: var(--navy); }
.sa-form-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 4px; }
.sa-checkbox-group { display: flex; flex-wrap: wrap; gap: 10px; }
.sa-checkbox { display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 500; color: var(--ink); background: var(--bg); padding: 7px 11px; border-radius: 7px; }
.sa-confirm-icon { color: var(--red); margin-bottom: 8px; }

/* ---------- Empty state ---------- */
.sa-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 6px; padding: 60px 20px; color: var(--muted); background: var(--card); border: 1px dashed var(--border); border-radius: 12px; }
.sa-empty h4 { font-family: 'Oswald', sans-serif; font-size: 15px; color: var(--ink); margin-top: 6px; }
.sa-muted-text { color: var(--muted); font-size: 13px; }

/* ---------- Student detail ---------- */
.sa-student-detail-head { display: flex; align-items: center; gap: 14px; margin-bottom: 16px; }
.sa-student-detail-head h3 { font-family: 'Oswald', sans-serif; font-size: 18px; }
.sa-student-detail-head p { font-size: 12.5px; color: var(--muted); }
.sa-student-detail-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 18px; }
.sa-student-detail-grid div { display: flex; flex-direction: column; gap: 3px; background: var(--bg); border-radius: 8px; padding: 10px 12px; }
.sa-student-detail-grid span { font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.5px; color: var(--muted); }
.sa-student-detail-grid strong { font-size: 13.5px; }
.sa-section-title { font-family: 'Oswald', sans-serif; font-size: 13.5px; text-transform: uppercase; letter-spacing: 0.6px; margin: 18px 0 10px; color: var(--navy); }
.sa-month-strip { display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; margin-bottom: 6px; }
.sa-month-cell { background: var(--bg); border-radius: 8px; padding: 8px; text-align: center; }
.sa-month-cell span { display: block; font-size: 10.5px; color: var(--muted); margin-bottom: 4px; }
.sa-month-cell strong { font-family: 'JetBrains Mono', monospace; font-size: 16px; color: var(--navy); }

/* ---------- Schedules / Calendar ---------- */
.sa-schedule-toolbar { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px; }
.sa-schedule-nav { display: flex; align-items: center; gap: 6px; }
.sa-schedule-label { font-family: 'Oswald', sans-serif; font-size: 15px; font-weight: 600; min-width: 170px; text-align: center; }
.sa-view-toggle { display: flex; background: var(--bg); border-radius: 8px; padding: 3px; }
.sa-view-toggle button { border: none; background: none; padding: 6px 14px; font-size: 12.5px; font-weight: 600; border-radius: 6px; cursor: pointer; color: var(--muted); }
.sa-toggle-active { background: var(--navy) !important; color: #fff !important; }
.sa-calendar { background: var(--card); border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
.sa-calendar-weekdays { display: grid; grid-template-columns: repeat(7, 1fr); background: var(--bg); }
.sa-calendar-weekdays div { padding: 8px; font-size: 11px; text-transform: uppercase; color: var(--muted); text-align: center; font-weight: 600; }
.sa-calendar-grid { display: grid; grid-template-columns: repeat(7, 1fr); }
.sa-calendar-grid-week { grid-auto-rows: 200px; }
.sa-calendar-cell { min-height: 96px; border-right: 1px solid #F0F1EE; border-bottom: 1px solid #F0F1EE; padding: 6px; cursor: pointer; }
.sa-calendar-cell:hover { background: #FAFAF8; }
.sa-calendar-cell-selected { background: #FFF4E0; }
.sa-calendar-cell-today .sa-calendar-daynum { background: var(--amber); color: var(--navy); }
.sa-calendar-cell-out { opacity: 0.35; }
.sa-calendar-daynum { display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; border-radius: 50%; font-size: 12px; font-weight: 600; }
.sa-calendar-chips { margin-top: 4px; display: flex; flex-direction: column; gap: 3px; }
.sa-calendar-chip { background: var(--navy); color: #fff; font-size: 10px; padding: 3px 5px; border-radius: 4px; overflow: hidden; text-overflow: ellipsis; line-height: 1.35; }
.sa-calendar-chip-time { font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sa-calendar-chip-batch { color: #C7D2E0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sa-calendar-more { font-size: 10px; color: var(--muted); }

.sa-day-panel { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 18px 20px; }
.sa-day-panel-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.sa-day-panel-head h3 { font-family: 'Oswald', sans-serif; font-size: 15.5px; font-weight: 600; }
.sa-session-list { display: flex; flex-direction: column; gap: 8px; }
.sa-session-row { display: flex; align-items: center; gap: 14px; background: var(--bg); border-radius: 9px; padding: 10px 12px; }
.sa-session-time { font-family: 'JetBrains Mono', monospace; font-weight: 700; color: var(--navy); width: 100px; font-size: 12.5px; }
.sa-session-info { display: flex; flex-direction: column; flex: 1; gap: 1px; }
.sa-session-info span { font-size: 12px; color: var(--muted); }
.sa-session-actions { display: flex; align-items: center; gap: 4px; }

.sa-attendance-list { display: flex; flex-direction: column; gap: 8px; }
.sa-attendance-row { display: flex; align-items: center; justify-content: space-between; background: var(--bg); border-radius: 9px; padding: 8px 12px; }
.sa-attendance-name { display: flex; align-items: center; gap: 10px; font-size: 13.5px; font-weight: 600; }
.sa-attendance-toggle { display: flex; gap: 6px; }
.sa-att-btn { border: 1px solid var(--border); background: var(--card); padding: 6px 12px; border-radius: 7px; font-size: 12px; font-weight: 600; cursor: pointer; color: var(--muted); }
.sa-att-btn-p { background: #CCFBF1; border-color: #14B8A6; color: #0F766E; }
.sa-att-btn-a { background: #FEE2E2; border-color: #EF4444; color: #B91C1C; }

.sa-att-toggle { display: inline-flex; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
.sa-att-toggle-btn {
  border: none; background: var(--card); padding: 6px 14px; cursor: pointer; color: var(--muted);
  display: flex; align-items: center; justify-content: center;
}
.sa-att-toggle-btn:first-child { border-right: 1px solid var(--border); }
.sa-att-toggle-p.sa-att-toggle-active { background: #14B8A6; color: #ffffff; }
.sa-att-toggle-a.sa-att-toggle-active { background: #EF4444; color: #ffffff; }

.sa-attendance-scroll { max-height: 722px; overflow-y: auto; }
.sa-attendance-scroll thead th { position: sticky; top: 0; z-index: 1; }

/* ---------- Fee Update ---------- */
.sa-search-results { margin-top: 10px; display: flex; flex-direction: column; gap: 4px; max-height: 220px; overflow-y: auto; }
.sa-search-result-row { display: flex; align-items: center; gap: 10px; padding: 8px; border-radius: 8px; cursor: pointer; }
.sa-search-result-row:hover { background: var(--bg); }
.sa-search-result-row span { color: var(--muted); font-size: 12px; }

/* ---------- Reports ---------- */
.sa-report-tabs { display: flex; gap: 6px; flex-wrap: wrap; }
.sa-report-tab { border: 1px solid var(--border); background: var(--card); padding: 9px 16px; border-radius: 8px; font-size: 13px; font-weight: 600; cursor: pointer; color: var(--muted); }
.sa-report-tab-active { background: var(--navy); color: #fff; border-color: var(--navy); }
.sa-report-filters { display: flex; align-items: flex-end; gap: 14px; flex-wrap: wrap; margin-bottom: 18px; }
.sa-attendance-header-strip { display: flex; gap: 8px; overflow-x: auto; margin-bottom: 14px; padding-bottom: 4px; }
.sa-att-header-cell { background: var(--bg); border-radius: 8px; padding: 8px 12px; text-align: center; flex-shrink: 0; min-width: 66px; }
.sa-att-header-cell span { display: block; font-size: 10px; color: var(--muted); }
.sa-att-header-cell strong { font-family: 'JetBrains Mono', monospace; font-size: 15px; color: var(--navy); }

@media (max-width: 900px) {
  .sa-dash-grid { grid-template-columns: 1fr; }
  .sa-form-row { grid-template-columns: 1fr; }
  .sa-student-detail-grid { grid-template-columns: repeat(2, 1fr); }

  .sa-sidebar {
    position: fixed; top: 0; left: 0; height: 100vh; width: 240px !important;
    z-index: 110; transform: translateX(-100%); transition: transform 0.25s ease; box-shadow: 4px 0 28px rgba(0,0,0,0.3);
  }
  .sa-sidebar.sa-sidebar-mobile-open { transform: translateX(0); }
  .sa-sidebar .sa-collapse-btn { display: none; }
  .sa-mobile-backdrop {
    display: block; position: fixed; inset: 0; background: rgba(15,27,45,0.5);
    z-index: 100; opacity: 0; pointer-events: none; transition: opacity 0.2s ease;
  }
  .sa-mobile-backdrop-visible { opacity: 1; pointer-events: auto; }
  .sa-hamburger-btn { display: inline-flex !important; }
  .sa-topbar { padding: 16px 18px; }
  .sa-content { padding: 18px; }
  .sa-scoreboard { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  .sa-attendance-table { table-layout: fixed; width: 100%; }
  .sa-attendance-table .sa-col-name { display: none; }
  .sa-attendance-table th, .sa-attendance-table td {
    padding: 6px 4px; font-size: 10.5px; white-space: normal; word-break: break-word; text-align: center;
  }
  .sa-attendance-table th:nth-child(2), .sa-attendance-table td:nth-child(2) { width: 22%; text-align: left; }
  .sa-attendance-table th:nth-child(3), .sa-attendance-table td:nth-child(3) { width: 13%; }
  .sa-attendance-table th:nth-child(4), .sa-attendance-table td:nth-child(4) { width: 18%; }
  .sa-attendance-table th:nth-child(5), .sa-attendance-table td:nth-child(5) { width: 18%; }
  .sa-attendance-table th:nth-child(6), .sa-attendance-table td:nth-child(6) { width: 29%; }
  .sa-attendance-table .sa-att-toggle-btn { padding: 5px 8px; }
  .sa-attendance-table .sa-pill { padding: 2px 5px; font-size: 9px; margin-left: 0; }
  .sa-attendance-scroll { max-height: 639px; }
}
`;
